import { Flow } from 'flow-sdk';
import React, { useState, useRef, useEffect, useCallback, memo } from 'react';
import { Icon } from './components/Icon';
import { Sidebar } from './components/Sidebar';
import { Stage } from './components/Stage';
import { Timeline } from './components/Timeline';
import {
    Layer, TextLayer, MediaLayer, LayerType,
    ProjectConfig, MediaAsset, FONTS, GOOGLE_FONTS_URL,
    isTextLayer, isMediaLayer
} from './types';
import { extractMaskPreview, extractMaskFromImage, ExtractionProgress } from './services/rotoscope';
import { clearPreviewCache } from './services/rotoscope';
import { timeController } from './services/TimeController';
import { createTextLayer, createMediaLayer, createSolidLayer } from './utils/layers';
import { useHistory } from './utils/useHistory';
import { useKeyboardShortcuts } from './utils/useKeyboardShortcuts';

const MemoizedSidebar = memo(Sidebar);

// ── Default Canvas ──
const DEFAULT_PROJECT: ProjectConfig = {
    canvasPresetName: '4:5',
    canvasWidth: 1080,
    canvasHeight: 1350,
    backgroundColor: '#121212',
    backgroundGradient: 'linear-gradient(160deg, #1a1a1a, #0d0d0d, #1f1f1f, #0a0a0a)',
};

// ── History snapshot shape ──
interface HistorySnapshot {
    layers: Layer[];
    projectConfig: ProjectConfig;
    selectedLayerId: string | null;
}

// ── Runtime injection of fonts + global CSS (index.html is ignored in Flow sandbox) ──
const INJECTED_STYLE_ID = 'poster-global-styles';
const INJECTED_FONT_ID = 'poster-material-symbols';
const INJECTED_BODY_FONT_ID = 'poster-google-sans';

function useGlobalStyles() {
    useEffect(() => {
        const preconnect1 = document.createElement('link');
        preconnect1.rel = 'preconnect';
        preconnect1.href = 'https://fonts.googleapis.com';
        document.head.appendChild(preconnect1);

        const preconnect2 = document.createElement('link');
        preconnect2.rel = 'preconnect';
        preconnect2.href = 'https://fonts.gstatic.com';
        preconnect2.crossOrigin = 'anonymous';
        document.head.appendChild(preconnect2);

        if (!document.getElementById(INJECTED_FONT_ID)) {
            const fontLink = document.createElement('link');
            fontLink.id = INJECTED_FONT_ID;
            fontLink.rel = 'stylesheet';
            fontLink.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
            document.head.appendChild(fontLink);
        }

        if (!document.getElementById(INJECTED_BODY_FONT_ID)) {
            const bodyFont = document.createElement('link');
            bodyFont.id = INJECTED_BODY_FONT_ID;
            bodyFont.rel = 'stylesheet';
            bodyFont.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&display=swap';
            document.head.appendChild(bodyFont);
        }

        // Load text layer fonts (all FONTS entries)
        const textFontLink = document.createElement('link');
        textFontLink.rel = 'stylesheet';
        textFontLink.crossOrigin = 'anonymous';
        textFontLink.href = GOOGLE_FONTS_URL;
        document.head.appendChild(textFontLink);

        if (!document.getElementById(INJECTED_STYLE_ID)) {
            const style = document.createElement('style');
            style.id = INJECTED_STYLE_ID;
            style.textContent = `\n                * { box-sizing: border-box; }\n                .material-symbols-rounded { font-variation-settings: 'FILL' 0, 'wght' 300, 'GRAD' 0, 'opsz' 20; }\n                .no-scrollbar::-webkit-scrollbar { display: none; }\n                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }\n\n                input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; }\n                input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 2px; background: #c0c0c0; border-radius: 9999px; }\n                input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 10px; height: 10px; border-radius: 50%; background: #888; border: none; margin-top: -4px; cursor: pointer; transition: background 0.15s; }\n                input[type=range]:hover::-webkit-slider-thumb { background: #555; }\n                input[type=range]::-moz-range-track { width: 100%; height: 2px; background: #c0c0c0; border-radius: 9999px; }\n                input[type=range]::-moz-range-thumb { width: 10px; height: 10px; border: none; border-radius: 50%; background: #888; cursor: pointer; }\n\n                .light-scrollbar { scrollbar-width: thin; scrollbar-color: #c0c0c0 transparent; }\n                .light-scrollbar::-webkit-scrollbar { width: 4px; }\n                .light-scrollbar::-webkit-scrollbar-track { background: transparent; }\n                .light-scrollbar::-webkit-scrollbar-thumb { background: #c0c0c0; border-radius: 9999px; }\n                .light-scrollbar::-webkit-scrollbar-thumb:hover { background: #aaa; }\n\n                @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }\n                .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }\n\n                @keyframes layer-enter { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }\n                .animate-layer { animation: layer-enter 0.2s ease-out forwards; }\n\n                .toolbar-btn { position: relative; }\n                .toolbar-btn .toolbar-tip { position: absolute; right: calc(100% + 8px); top: 50%; transform: translateY(-50%); background: white; border: 0.5px solid black; border-radius: 8px; padding: 4px 8px; white-space: nowrap; font-family: 'Google Sans', sans-serif; font-size: 8px; color: black; opacity: 0; pointer-events: none; transition: opacity 0.15s; }\n                .toolbar-btn:hover .toolbar-tip { opacity: 1; }\n\n                html, body, #root {\n                    margin: 0; padding: 0; width: 100%; height: 100%;\n                    background: black;\n                    font-family: 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n                    -webkit-font-smoothing: antialiased;\n                    -moz-osx-font-smoothing: grayscale;\n                }\n\n                .card { width: 100%; background: white; border-radius: 10px; box-shadow: 0px 4px 4px 0px rgba(0,0,0,0.25); padding: 12px 12px 16px; display: flex; flex-direction: column; gap: 16px; }\n                .accent-bar { position: absolute; top: -7px; left: 50%; transform: translateX(-50%); width: 87px; height: 14px; background: #4dff00; box-shadow: 0px 2px 4px 0px rgba(0,0,0,0.25); z-index: 20; }\n                .toolbar-circle { width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; border-radius: 9999px; background: #ececec; cursor: pointer; transition: background-color 0.15s; }\n                .toolbar-circle:hover { background: white; }\n                .toolbar-circle:disabled { opacity: 0.4; cursor: not-allowed; }\n                .section-label { font-size: 10px; font-weight: 700; color: black; letter-spacing: -0.6px; text-transform: uppercase; }\n            `;
            document.head.appendChild(style);
        }

        return () => {
            preconnect1.remove();
            preconnect2.remove();
            textFontLink.remove();
        };
    }, []);
}

export default function App() {
    useGlobalStyles();

    const [projectConfig, setProjectConfig] = useState<ProjectConfig>(DEFAULT_PROJECT);
    const [layers, setLayers] = useState<Layer[]>([
        createTextLayer({ zIndex: 2, content: 'Hasty work' + String.fromCharCode(10) + 'is a shame for' + String.fromCharCode(10) + 'the craftsman' }),
    ]);
    const [selectedLayerId, setSelectedLayerId] = useState<string | null>(layers[0]?.id || null);
    const [duration, setDuration] = useState(8);
    const [isPlaying, setIsPlaying] = useState(false);
    const [isRendering, setIsRendering] = useState(false);
    const [renderProgress, setRenderProgress] = useState(0);
    const [isExtracting, setIsExtracting] = useState(false);
    const [extractionProgress, setExtractionProgress] = useState(0);
    const [exportedMedia, setExportedMedia] = useState<{ dataUrl: string, mimeType: string } | null>(null);
    const prevExportUrl = useRef<string | null>(null);
    const [key, setKey] = useState(0);
    const [, forceRender] = useState(0);

    // Abort controller for cancellable render
    const renderAbortRef = useRef<AbortController | null>(null);
    // Clipboard for copy/paste
    const clipboardRef = useRef<Layer | null>(null);

    // Always-fresh refs to avoid stale closures in callbacks
    const layersRef = useRef(layers);
    layersRef.current = layers;
    const projectConfigRef = useRef(projectConfig);
    projectConfigRef.current = projectConfig;
    const selectedLayerIdRef = useRef(selectedLayerId);
    selectedLayerIdRef.current = selectedLayerId;

    /** Revoke the previous export URL before setting a new one */
    const setExportResult = useCallback((result: { dataUrl: string, mimeType: string } | null) => {
        if (prevExportUrl.current) {
            URL.revokeObjectURL(prevExportUrl.current);
            prevExportUrl.current = null;
        }
        if (result && result.dataUrl.startsWith('blob:')) {
            prevExportUrl.current = result.dataUrl;
        }
        setExportedMedia(result);
    }, []);

    /** Revoke blob URLs held by a layer (media object URLs) */
    const revokeLayerUrls = useCallback((layer: Layer) => {
        if (isMediaLayer(layer) && layer.mediaAsset.dataUrl.startsWith('blob:')) {
            URL.revokeObjectURL(layer.mediaAsset.dataUrl);
        }
    }, []);

    // ── Undo / Redo ──
    const history = useHistory<HistorySnapshot>(100);
    const isRestoringRef = useRef(false);

    // Seed history with initial state (runs once)
    useEffect(() => {
        history.reset({ layers, projectConfig, selectedLayerId });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    /** Push a snapshot after a user-initiated mutation. */
    const pushHistory = useCallback((newLayers: Layer[], newConfig: ProjectConfig, newSelectedId: string | null) => {
        if (isRestoringRef.current) return;
        history.push({ layers: newLayers, projectConfig: newConfig, selectedLayerId: newSelectedId });
        forceRender(n => n + 1); // refresh canUndo/canRedo
    }, [history]);

    const handleUndo = useCallback(() => {
        const snapshot = history.undo();
        if (!snapshot) return;
        isRestoringRef.current = true;
        setLayers(snapshot.layers);
        setProjectConfig(snapshot.projectConfig);
        setSelectedLayerId(snapshot.selectedLayerId);
        isRestoringRef.current = false;
        forceRender(n => n + 1);
    }, [history]);

    const handleRedo = useCallback(() => {
        const snapshot = history.redo();
        if (!snapshot) return;
        isRestoringRef.current = true;
        setLayers(snapshot.layers);
        setProjectConfig(snapshot.projectConfig);
        setSelectedLayerId(snapshot.selectedLayerId);
        isRestoringRef.current = false;
        forceRender(n => n + 1);
    }, [history]);

    // ── Layer CRUD ──

    const getNextZIndex = useCallback(() => {
        const cur = layersRef.current;
        return cur.length > 0 ? Math.max(...cur.map(l => l.zIndex)) + 1 : 1;
    }, []);

    const handleAddLayer = useCallback((type: LayerType) => {
        const zIndex = getNextZIndex();
        const fullDurationMs = duration * 1000;
        let newLayer: Layer;

        if (type === 'text') {
            newLayer = createTextLayer({ zIndex, delay: 0, duration: fullDurationMs });
        } else if (type === 'solid-color') {
            newLayer = createSolidLayer({ zIndex, delay: 0, duration: fullDurationMs });
        } else {
            // For image/video, open file picker
            handleAddMedia(zIndex);
            return;
        }

        const newLayers = [...layersRef.current, newLayer];
        setLayers(newLayers);
        setSelectedLayerId(newLayer.id);
        pushHistory(newLayers, projectConfigRef.current, newLayer.id);
    }, [getNextZIndex, pushHistory, duration]);

    const handleAddMedia = useCallback(async (zIndex?: number) => {
        try {
            const media = await Flow.media.select({ filter: 'all' });
            if (!media) return;

            const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
            const blob = new Blob([bytes], { type: media.mimeType });
            const file = new File([blob], media.name || 'import', { type: media.mimeType });
            const objectUrl = URL.createObjectURL(file);
            const mediaType = media.type;
            const rawName = media.name || 'asset';
            const fileName = (rawName.includes('.') ? rawName.slice(0, rawName.lastIndexOf('.')) : rawName).slice(0, 20);

            if (mediaType === 'video') {
                const probe = document.createElement('video');
                probe.muted = true;
                probe.preload = 'metadata';
                probe.onloadedmetadata = () => {
                    const nw = probe.videoWidth;
                    const nh = probe.videoHeight;
                    const asset: MediaAsset = { type: 'video', dataUrl: objectUrl, mimeType: file.type, naturalWidth: nw, naturalHeight: nh };
                    const newLayer = createMediaLayer(asset, { zIndex: zIndex ?? getNextZIndex(), name: fileName });
                    const next = [...layersRef.current, newLayer];
                    setLayers(next);
                    setSelectedLayerId(newLayer.id);
                    pushHistory(next, projectConfigRef.current, newLayer.id);
                    setIsPlaying(true);
                    timeController.setTime(0);
                    probe.remove();
                };
                probe.src = objectUrl;
            } else if (mediaType === 'image') {
                const img = new Image();
                img.onload = () => {
                    const nw = img.naturalWidth;
                    const nh = img.naturalHeight;
                    const asset: MediaAsset = { type: 'image', dataUrl: objectUrl, mimeType: file.type, naturalWidth: nw, naturalHeight: nh };
                    const newLayer = createMediaLayer(asset, { zIndex: zIndex ?? getNextZIndex(), name: fileName });
                    const next = [...layersRef.current, newLayer];
                    setLayers(next);
                    setSelectedLayerId(newLayer.id);
                    pushHistory(next, projectConfigRef.current, newLayer.id);
                };
                img.src = objectUrl;
            }
        } catch (err) {
            console.error('Failed to select media:', err);
        }
    }, [getNextZIndex, pushHistory]);

    const handleDeleteLayer = useCallback((id: string) => {
        const cur = layersRef.current;
        const deleted = cur.find(l => l.id === id);
        if (deleted) {
            revokeLayerUrls(deleted);
            // Free cached mask data if this was a masked layer
            if (isMediaLayer(deleted) && deleted.hasMask) clearPreviewCache(id);
        }
        const remaining = cur.filter(l => l.id !== id);
        let nextSelected = selectedLayerIdRef.current;
        if (selectedLayerIdRef.current === id) {
            const idx = cur.findIndex(l => l.id === id);
            const next = cur[idx + 1] ?? cur[idx - 1];
            nextSelected = next?.id || null;
            setSelectedLayerId(nextSelected);
        }
        setLayers(remaining);
        pushHistory(remaining, projectConfigRef.current, nextSelected);
    }, [pushHistory, revokeLayerUrls]);

    const handleUpdateLayer = useCallback((id: string, updates: Partial<Layer>) => {
        const next = layersRef.current.map(l => l.id === id ? { ...l, ...updates } as Layer : l);
        setLayers(next);
        pushHistory(next, projectConfigRef.current, selectedLayerIdRef.current);
    }, [pushHistory]);

    const handleReorderLayers = useCallback((newLayers: Layer[]) => {
        setLayers(newLayers);
        pushHistory(newLayers, projectConfigRef.current, selectedLayerIdRef.current);
    }, [pushHistory]);

    const handleBatchUpdate = useCallback((updates: Array<{ id: string; changes: Partial<Layer> }>) => {
        const next = layersRef.current.map(l => {
            const update = updates.find(u => u.id === l.id);
            return update ? { ...l, ...update.changes } as Layer : l;
        });
        setLayers(next);
        pushHistory(next, projectConfigRef.current, selectedLayerIdRef.current);
    }, [pushHistory]);

    // Live position update during drag — NO history push (fires every mousemove)
    const handleUpdateLayerPosition = useCallback((id: string, pos: { x: number; y: number }) => {
        setLayers(prev => prev.map(l => {
            if (l.id !== id) return l;
            if ('position' in l) return { ...l, position: pos } as Layer;
            return l;
        }));
    }, []);

    // Called once on mouseup — push a single history snapshot for the whole drag
    const handleDragEnd = useCallback(() => {
        pushHistory(layersRef.current, projectConfigRef.current, selectedLayerIdRef.current);
    }, [pushHistory]);

    const handleVideoMetadataLoaded = useCallback((layerId: string, videoDuration: number) => {
        const newDurMs = videoDuration * 1000;
        handleUpdateLayer(layerId, { duration: newDurMs });
        // Always remap timeline to match video length (both expand and shrink)
        setDuration(videoDuration);
        // Clamp existing layers so they don't extend past the new timeline end
        setLayers(prev => prev.map(l => {
            if (l.id === layerId) return l; // video layer already updated
            const clampedDelay = Math.min(l.delay, newDurMs);
            const maxDur = newDurMs - clampedDelay;
            const clampedDuration = Math.min(l.duration, maxDur);
            if (clampedDelay !== l.delay || clampedDuration !== l.duration) {
                return { ...l, delay: clampedDelay, duration: clampedDuration };
            }
            return l;
        }));
    }, [handleUpdateLayer]);

    // ── Mask Extraction (Phase 1: Preview) ──

    const handleExtractSubject = useCallback(async () => {
        const selected = layersRef.current.find(l => l.id === selectedLayerIdRef.current);
        if (!selected || !isMediaLayer(selected)) return;

        const sourceAsset = selected.mediaAsset;

        setIsExtracting(true);
        setExtractionProgress(0);

        try {
            const onProgress = (p: ExtractionProgress) => setExtractionProgress(p.progress);
            const currentTime = timeController.getTime();

            if (sourceAsset.type === 'video') {
                await extractMaskPreview(
                    sourceAsset.dataUrl, currentTime, selected.id, onProgress
                );
            } else {
                await extractMaskFromImage(
                    sourceAsset.dataUrl, selected.id, onProgress
                );
            }

            // Apply mask in-place on the existing media layer
            handleUpdateLayer(selected.id, {
                hasMask: true,
                threshold: selected.threshold ?? 0.5,
                invert: selected.invert ?? false,
                choke: selected.choke ?? 0,
                feather: selected.feather ?? 0,
            });
        } catch (err) {
            console.error('Mask extraction failed:', err);
        } finally {
            setIsExtracting(false);
            setExtractionProgress(0);
        }
    }, [handleUpdateLayer]);

    // ── Cancel Extraction ──

    const handleCancelExtraction = useCallback(() => {
        setIsExtracting(false);
        setExtractionProgress(0);
    }, []);


    // ── Project Config ──

    const handleUpdateProjectConfig = useCallback((updates: Partial<ProjectConfig>) => {
        const next = { ...projectConfigRef.current, ...updates };
        setProjectConfig(next);
        pushHistory(layersRef.current, next, selectedLayerIdRef.current);
    }, [pushHistory]);

    // ── Keyboard Shortcuts ──

    useKeyboardShortcuts({
        layersRef, selectedLayerIdRef, projectConfigRef, clipboardRef,
        setLayers, setSelectedLayerId, setIsPlaying,
        getNextZIndex, pushHistory,
        handleDeleteLayer, handleUpdateLayer, handleUndo, handleRedo,
    });

    // ── Playback ──

    const handleRestart = useCallback(() => {
        setKey(prev => prev + 1);
        timeController.setTime(0);
        setIsPlaying(false);
        requestAnimationFrame(() => setIsPlaying(true));
    }, []);

    const handleTimelineSeek = useCallback((time: number) => {
        timeController.setTime(time);
    }, []);

    // ── Export ──

    const handleExport = async () => {
        if (isRendering || layers.length === 0) return;

        setIsRendering(true);
        setRenderProgress(0);
        const abortCtrl = new AbortController();
        renderAbortRef.current = abortCtrl;

        // Pause playback during export
        const wasPlaying = isPlaying;
        setIsPlaying(false);

        try {
            const cur = layersRef.current;
            const hasVideo = cur.some(l => l.visible && isMediaLayer(l) && l.mediaAsset.type === 'video');
            const hasAnimatedText = cur.some(l => l.visible && isTextLayer(l) && l.effect !== 'none');

            if (hasVideo || hasAnimatedText) {
                const { renderVideoExport } = await import('./services/renderer');
                const result = await renderVideoExport(
                    layersRef.current,
                    projectConfigRef.current,
                    (p) => setRenderProgress(p),
                    abortCtrl.signal,
                    duration,
                );
                setExportResult(result);
            } else {
                const { renderStillExport } = await import('./services/renderer');
                const result = await renderStillExport(layersRef.current, projectConfigRef.current);
                setExportResult(result);
            }
        } catch (err: any) {
            if (err?.name === 'AbortError' || err?.message === 'Render cancelled') {
                console.log('Render cancelled by user');
            } else {
                console.error('Export failed:', err);
                alert('Export failed — check console for details.');
            }
        } finally {
            renderAbortRef.current = null;
            setIsRendering(false);
            setRenderProgress(0);
            if (wasPlaying) setIsPlaying(true);
        }
    };

    const handleCancelRender = useCallback(() => {
        if (renderAbortRef.current) {
            renderAbortRef.current.abort();
            renderAbortRef.current = null;
        }
        setIsRendering(false);
        setRenderProgress(0);
    }, []);

    // ── I'm Feeling Lucky (Randomize) ──
    const handleRandomize = useCallback(() => {
        const cur = layersRef.current;
        const textLayers = cur.filter(isTextLayer);
        if (textLayers.length === 0) return;

        const sid = selectedLayerIdRef.current;
        const target = textLayers.find(l => l.id === sid) ?? textLayers[0];
        const randomFont = FONTS[Math.floor(Math.random() * FONTS.length)];
        const randomWeight = randomFont.weights[Math.floor(Math.random() * randomFont.weights.length)];
        const randomColor = '#' + Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
        const randomSize = 40 + Math.floor(Math.random() * 200);
        const randomLetterSpacing = -10 + Math.floor(Math.random() * 50);
        const effects: Array<TextLayer['effect']> = ['blur-in', 'typewriter', 'explode', 'slide-fade', 'wave', 'wiggle', 'sequential-stack'];
        const randomEffect = effects[Math.floor(Math.random() * effects.length)];

        handleUpdateLayer(target.id, {
            fontFamily: randomFont.family,
            fontWeight: randomWeight,
            color: randomColor,
            fontSize: randomSize,
            letterSpacing: randomLetterSpacing,
            effect: randomEffect,
        });
        setSelectedLayerId(target.id);
    }, [handleUpdateLayer]);

    // ── Screenshot (capture current frame at full res) ──
    const handleScreenshot = useCallback(async () => {
        if (isRendering || layers.length === 0) return;
        // Lock time immediately so playback can't advance during async import
        const savedTime = timeController.getTime();
        timeController.isLocked = true;
        setIsRendering(true);
        setRenderProgress(0);
        const wasPlaying = isPlaying;
        setIsPlaying(false);
        try {
            const { renderStillExport } = await import('./services/renderer');
            const result = await renderStillExport(layersRef.current, projectConfigRef.current, savedTime);
            setExportResult(result);
        } catch (err) {
            console.error('Screenshot failed:', err);
        } finally {
            timeController.isLocked = false;
            setIsRendering(false);
            setRenderProgress(0);
            if (wasPlaying) setIsPlaying(true);
        }
    }, [isRendering, layers.length, isPlaying, setExportResult]);

    const selectedLayer = layers.find(l => l.id === selectedLayerId) || null;

    return (
        <div className="fixed inset-0 w-screen h-screen bg-black text-black flex overflow-hidden">
            {/* ── Left Column: Canvas + Timeline ── */}
            <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden">
                {/* Canvas Area */}
                <div className="relative flex-1 flex items-center justify-center min-h-0 p-6 lg:p-8 overflow-hidden bg-black">
                    <Stage
                        layers={layers}
                        projectConfig={projectConfig}
                        selectedLayerId={isRendering ? null : selectedLayerId}
                        isPlaying={isPlaying}
                        animationKey={key}
                        duration={duration}
                        onUpdateLayerPosition={handleUpdateLayerPosition}
                        onUpdateLayer={handleUpdateLayer}
                        onDragEnd={handleDragEnd}
                        onVideoMetadataLoaded={handleVideoMetadataLoaded}
                        onSelectLayer={setSelectedLayerId}
                        placeholderDuration={duration}
                    />
                    {/* Undo/Redo – bottom-right of canvas */}
                    <div className="absolute bottom-4 right-4 flex items-center gap-[6px] z-30">
                        <button
                            className="toolbar-circle"
                            onClick={handleUndo}
                            disabled={!history.canUndo()}
                            title="Undo (⌘Z)"
                        >
                            <Icon name="undo" size={16} className={history.canUndo() ? 'text-black' : 'text-black/25'} />
                        </button>
                        <button
                            className="toolbar-circle"
                            onClick={handleRedo}
                            disabled={!history.canRedo()}
                            title="Redo (⌘⇧Z)"
                        >
                            <span className="inline-flex -scale-x-100">
                                <Icon name="undo" size={16} className={history.canRedo() ? 'text-black' : 'text-black/25'} />
                            </span>
                        </button>
                    </div>

                    {/* ── Vertical Toolbar ── */}
                    <div className="absolute top-[20px] right-4 flex flex-col items-center gap-[6px] z-30">
                        {/* Upload Media */}
                        <div className="toolbar-btn">
