            {/* Export Popup */}
            {exportedMedia && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-8" onClick={() => setExportResult(null)}>
                    <div className="bg-white border-[0.5px] border-black rounded-[10px] p-5 shadow-2xl max-w-2xl w-full flex flex-col gap-5" onClick={(e) => e.stopPropagation()}>
