                            <h2 className="section-label">Render Complete</h2>
                            <button onClick={() => setExportResult(null)} className="text-[rgba(0,0,0,0.3)] hover:text-black transition-colors p-1">
                                <Icon name="close" size={16} />
                            </button>
                        </div>
                        <div className="rounded-[10px] overflow-hidden bg-black border-[0.5px] border-black flex items-center justify-center min-h-[300px]">
                            {exportedMedia.mimeType.startsWith('video/') ? (
                                <video src={exportedMedia.dataUrl} controls autoPlay loop className="max-h-[60vh] max-w-full object-contain" />
                            ) : (
                                <img src={exportedMedia.dataUrl} alt="Exported result" className="max-h-[60vh] max-w-full object-contain" />
                            )}
                        </div>
                        <div className="flex gap-[5px] pt-2">
                            <button onClick={() => setExportResult(null)}
                                className="flex-1 h-[34px] rounded-[8px] border-[0.5px] border-black hover:bg-black/5 active:bg-black/10 text-[12px] font-medium text-black tracking-[-0.56px] transition-all cursor-pointer select-none">
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Rendering Overlay */}
            {isRendering && (
                <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center">
                    <div className="flex flex-col items-center gap-4">
                        <Icon name="progress_activity" size={36} className="animate-spin text-white" />
                        <span className="text-[16px] font-medium text-white tracking-[-0.56px]">
                            Rendering {Math.round(renderProgress * 100)}%
                        </span>
                        <span className="text-[13px] text-white/60 tracking-[-0.3px] text-center max-w-[280px] leading-[1.5]">
                            This may take a minute. Please don&apos;t switch tabs or minimize the window.
                        </span>
                        <button
                            onClick={handleCancelRender}
                            className="mt-2 px-6 h-[36px] rounded-[8px] border-[0.5px] border-white/40 hover:bg-white/10 active:bg-white/20 text-[13px] font-medium text-white tracking-[-0.56px] transition-all cursor-pointer select-none"
                        >
                            Cancel
                        </button>
                    </div>
                </div>
            )}

            {/* Extraction Overlay */}
            {isExtracting && (
                <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center">
                    <div className="flex flex-col items-center gap-4 bg-white border-[0.5px] border-black rounded-[10px] p-8 shadow-2xl">
                        <Icon name="person_search" size={32} className="text-black" />
                        <span className="text-[14px] font-medium text-black tracking-[-0.56px]">
                            Extracting Subject...
                        </span>
                        <div className="w-48 h-1 bg-black/10 rounded-full overflow-hidden">
                            <div
                                className="h-full bg-black rounded-full transition-all duration-300"
                                style={{ width: `${Math.round(extractionProgress * 100)}%` }}
                            />
                        </div>
                        <span className="text-[10px] text-[rgba(0,0,0,0.4)]">
                            {Math.round(extractionProgress * 100)}%
                        </span>
                        <span className="text-[10px] text-[rgba(0,0,0,0.35)] tracking-[-0.3px] text-center max-w-[240px] leading-[1.5]">
                            This may take a minute. Please don&apos;t switch tabs or minimize the window.
                        </span>
                        <button
                            onClick={handleCancelExtraction}
                            className="mt-1 px-6 h-[34px] rounded-[8px] border-[0.5px] border-black hover:bg-black/5 active:bg-black/10 text-[12px] font-medium text-black tracking-[-0.56px] transition-all cursor-pointer select-none"
                        >
                            Cancel
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { useEffect, useRef, useMemo, memo, useCallback } from 'react';
import { createTimeline, stagger, splitText, steps, spring, utils } from 'animejs';
import { TextLayer, FONTS, KINETIC_EFFECTS } from '../types';
import { BoundingBox } from './BoundingBox';
import { timeController } from '../services/TimeController';

interface AnimatedTextProps {
    config: TextLayer;
    isPlaying: boolean;
    animationKey: number;
    selectedId: string | null;
    onSelectLayer: (e: React.MouseEvent, id: string) => void;
    onUpdateLayer?: (id: string, updates: Partial<TextLayer>) => void;
    onResizeEnd?: () => void;
}

const FONT_FAMILIES = FONTS.map(f => f.family);

// Module-level style injection — runs once, not per effect rebuild (#5)
const STYLE_ID = 'typestroke-animation-styles';
if (typeof document !== 'undefined' && !document.getElementById(STYLE_ID)) {
    const styleEl = document.createElement('style');
    styleEl.id = STYLE_ID;
    styleEl.innerHTML = `\n        .stack-container { display: grid; place-items: center; width: 100%; height: 100%; }\n        .stack-item { grid-area: 1 / 1 / 2 / 2; opacity: 0; }\n        .line-wrap { display: block; }\n    `;
    document.head.appendChild(styleEl);
}

function seededRandom(seed: number): number {
    const x = Math.sin(seed * 12.9898 + 78.233) * 43758.5453;
    return x - Math.floor(x);
}

function applyKineticFrame(effect: string, elements: HTMLElement[], localTimeMs: number, speed: number, intensity: number, lineIndices: number[] = []) {
    const n = elements.length;
    if (n === 0) return;
    const s = speed || 1;
    const amp = (intensity || 50) / 50;

    if (effect === 'wave') {
        const freq = s * 0.008;
        const maxY = amp * 12;
        elements.forEach((el, i) => {
            const idx = lineIndices.length > 0 ? lineIndices[i] : i;
            const y = Math.sin(localTimeMs * freq + idx * 0.7) * maxY;
            el.style.transform = `translateY(${y}px)`;
        });
    } else if (effect === 'wiggle') {
        const updateRate = Math.max(30, 200 / s);
        const tick = Math.floor(localTimeMs / updateRate);
        const maxShift = amp * 4;
        elements.forEach((el, i) => {
            const sx = seededRandom(tick * 137 + i * 31);
            const sy = seededRandom(tick * 251 + i * 53);
            el.style.transform = `translate(${(sx - 0.5) * maxShift * 2}px, ${(sy - 0.5) * maxShift * 2}px)`;
        });
    } else if (effect === 'font-shuffle') {
        const interval = Math.max(50, 400 / s);
        const tick = Math.floor(localTimeMs / interval);
        elements.forEach((el, i) => {
            const fontIdx = Math.floor(seededRandom(tick * 73 + i * 17) * FONT_FAMILIES.length);
            el.style.fontFamily = FONT_FAMILIES[fontIdx];
        });
    }
}

function getAnimParts(
    h2: HTMLElement,
    granularity: string,
    root: HTMLElement,
    effect: string
): { parts: HTMLElement[] | null; splitter: any } {
    if (granularity === 'line') {
        // Lines are manually split (anime.js lines are async/unreliable for seek)
        const lineEls = root.querySelectorAll('.line-wrap');
        return {
            parts: lineEls.length > 0 ? Array.from(lineEls) as HTMLElement[] : null,
            splitter: null
        };
    }

    const splitKey = granularity === 'word' ? 'words' : 'chars';

    const splitOpts: any = {};
    if (splitKey === 'words') {
        splitOpts.words = true;
    } else {
        splitOpts.chars = true;
    }

    const splitter = splitText(h2, splitOpts);
    const parts = splitter[splitKey as 'chars' | 'words'];
    return {
        parts: (parts && parts.length > 0) ? Array.from(parts) as HTMLElement[] : null,
        splitter
    };
}

/** Shared stagger timing calculation used by blur-in, slide-up, slide-fade (#10) */
function computeStagger(n: number, inDur: number, granularity: string) {
    const perDur = Math.min(
        granularity === 'line' ? Math.max(200, inDur * 0.5)
        : granularity === 'char' ? Math.max(80, inDur * 0.3)
        : Math.max(150, inDur * 0.4),
        inDur
    );
    const sd = n > 1 ? Math.max(0, (inDur - perDur) / (n - 1)) : 0;
    return { perDur, sd };
}

const AnimatedTextComponent: React.FC<AnimatedTextProps> = ({ config, isPlaying, animationKey, selectedId, onSelectLayer, onUpdateLayer, onResizeEnd }) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const timelineRef = useRef<any>(null);
    const splitterRef = useRef<any>(null);
    const kineticPartsRef = useRef<HTMLElement[]>([]);
    const kineticTypeRef = useRef<string | null>(null);
    const kineticLineIndicesRef = useRef<number[]>([]);
    const configRef = useRef(config);
    configRef.current = config;
    const resizeStartFontSize = useRef<number>(0);

    const styles = useMemo(() => ({
        fontFamily: config.fontFamily,
        fontSize: `${config.fontSize}px`,
        fontWeight: config.fontWeight,
        letterSpacing: `${config.letterSpacing}px`,
        textAlign: config.textAlign as any,
        color: config.color,
        lineHeight: config.lineHeight,
        whiteSpace: 'pre-wrap' as const,
    }), [config.fontFamily, config.fontSize, config.fontWeight, config.letterSpacing, config.textAlign, config.color, config.lineHeight]);

    // Build animation
    useEffect(() => {
        if (!rootRef.current) return;

        // Clean up previous splitter to avoid DOM leaks (#4)
        if (splitterRef.current) {
            try { splitterRef.current.revert(); } catch {}
            splitterRef.current = null;
        }

        const content = config.content || '';
        const speedMul = 1 / (config.speed || 1);
        const inEase = config.easing === 'linear' ? 'linear' : spring({ bounce: 0.5, duration: 628 });
        const outEase = config.easing === 'linear' ? 'linear' : spring({ bounce: 0, duration: 400 });
        const granularity = config.granularity || 'word';
        const isKinetic = KINETIC_EFFECTS.has(config.effect);
        const isStackLayout = config.effect === 'sequential-stack';

        // Reset
        kineticPartsRef.current = [];
        kineticTypeRef.current = null;
        timelineRef.current = null;

        // === HTML Generation ===
        if (isStackLayout) {
            let segments: string[];
            if (granularity === 'char') {
                segments = content.split('').filter(c => c.trim().length > 0);
            } else if (granularity === 'line') {
                segments = content.split(String.fromCharCode(10)).filter(l => l.trim().length > 0);
                if (segments.length < 2) segments = content.split(' ').filter(w => w.length > 0);
            } else {
                segments = content.split(' ').filter(w => w.length > 0);
            }
            rootRef.current.innerHTML = `${'<'}div class="stack-container"${'>'} ${segments.map(s => `${'<'}h2 class="stack-item"${'>'} ${s}<${'/'}h2>`).join('')}<${'/'}div>`;
        } else if (granularity === 'line' && config.effect !== 'none') {
            const lines = content.split(String.fromCharCode(10));
            rootRef.current.innerHTML = `${'<'}h2${'>'} ${lines.map(l => `${'<'}span class="line-wrap"${'>'} ${l || '&nbsp;'}<${'/'}span>`).join('')}<${'/'}h2>`;
        } else {
            rootRef.current.innerHTML = `${'<'}h2${'>'} ${content}<${'/'}h2>`;
        }

        const h2 = rootRef.current.querySelector('h2')!;
        const applyStyles = (el: HTMLElement) => {
            el.style.margin = '0'; el.style.padding = '0';
            el.style.fontSize = 'inherit'; el.style.fontWeight = 'inherit';
            el.style.fontFamily = 'inherit'; el.style.color = 'inherit';
            el.style.textAlign = 'inherit'; el.style.letterSpacing = 'inherit';
            el.style.lineHeight = config.lineHeight.toString();
            el.style.whiteSpace = 'pre-wrap';
        };
        if (isStackLayout) {
            rootRef.current.querySelectorAll('.stack-item').forEach(el => applyStyles(el as HTMLElement));
        } else {
            applyStyles(h2);
        }

        if (config.effect === 'none') return;

        // === Kinetic effects: store refs, no timeline ===
        if (isKinetic) {
            kineticTypeRef.current = config.effect;
            // wave, wiggle, font-shuffle: split into chars/words
            const { parts, splitter: sp } = getAnimParts(h2, granularity, rootRef.current, config.effect);
            kineticPartsRef.current = parts || [];
            splitterRef.current = sp;

            // Compute per-line indices for wave sync
            if (config.effect === 'wave' && parts && parts.length > 0) {
                const indices: number[] = [];
                let currentTop = -Infinity;
                let lineIdx = 0;
                parts.forEach(el => {
                    const top = el.offsetTop;
                    if (Math.abs(top - currentTop) > 2) {
                        currentTop = top;
                        lineIdx = 0;
                    }
                    indices.push(lineIdx);
                    lineIdx++;
                });
                kineticLineIndicesRef.current = indices;
            } else {
                kineticLineIndicesRef.current = [];
            }
            return;
        }

        // === Timeline-based effects ===
        const tl = createTimeline({ autoplay: false });
        const inDur = config.inDuration * speedMul;
        const outDur = config.outDuration * speedMul;
        const inStart = config.delay;
        const outStart = config.delay + config.duration - outDur;

        if (config.effect === 'sequential-stack') {
            const items = rootRef.current.querySelectorAll('.stack-item');
            const effectiveDuration = config.duration / (config.speed || 1);
            const step = effectiveDuration / Math.max(items.length, 1);
            const transition = config.stackTransition || 'blur';

            if (transition === 'blur') {
                tl.add(items, { opacity: [0, 1], scale: [0.8, 1], filter: ['blur(10px)', 'blur(0px)'], duration: Math.min(300, step * 0.4), ease: inEase, delay: stagger(step, { start: config.delay }) });
                items.forEach((item, i) => { if (i < items.length - 1) tl.add(item, { opacity: 0, scale: 1.2, filter: 'blur(5px)', duration: Math.min(200, step * 0.3), ease: outEase }, config.delay + (step * (i + 1)) - Math.min(100, step * 0.15)); });
            } else if (transition === 'cut') {
                tl.add(items, { opacity: [0, 1], duration: 1, ease: steps(1), delay: stagger(step, { start: config.delay }) });
                items.forEach((item, i) => { if (i < items.length - 1) tl.add(item, { opacity: 0, duration: 1, ease: steps(1) }, config.delay + (step * (i + 1))); });
            } else if (transition === 'fade') {
                tl.add(items, { opacity: [0, 1], duration: Math.min(250, step * 0.4), ease: inEase, delay: stagger(step, { start: config.delay }) });
                items.forEach((item, i) => { if (i < items.length - 1) tl.add(item, { opacity: 0, duration: Math.min(200, step * 0.3), ease: outEase }, config.delay + (step * (i + 1)) - Math.min(100, step * 0.15)); });
            }
        } else {
            // Shared logic for blur-in, typewriter, slide-up, slide-fade
            const { parts, splitter: sp } = getAnimParts(h2, granularity, rootRef.current, config.effect);
            splitterRef.current = sp;
            if (parts && parts.length > 0) {
                const n = parts.length;

                if (config.effect === 'typewriter') {
                    if (inDur > 0) {
                        const stepDur = 1;
                        const staggerInt = n > 1 ? (inDur - stepDur) / (n - 1) : 0;
                        tl.add(parts, { opacity: [0, 1], ease: steps(1), duration: stepDur, delay: stagger(staggerInt) }, inStart);
                    }
                    if (outDur > 0) {
                        const stepDur = 1;
                        const outStagger = n > 1 ? (outDur - stepDur) / (n - 1) : 0;
                        tl.add(parts, { opacity: [1, 0], duration: 1, ease: steps(1), delay: stagger(outStagger) }, outStart);
                    }

                } else if (config.effect === 'blur-in') {
                    if (inDur > 0) {
                        const { perDur, sd } = computeStagger(n, inDur, granularity);
                        tl.add(parts, { opacity: [0, 1], y: [20, 0], filter: ['blur(10px)', 'blur(0px)'], ease: inEase, duration: perDur, delay: stagger(sd) }, inStart);
                    }
                    if (outDur > 0) { const { perDur: od, sd: osd } = computeStagger(n, outDur, granularity); tl.add(parts, { opacity: [1, 0], filter: ['blur(0px)', 'blur(10px)'], y: [0, -20], duration: od, ease: outEase, delay: stagger(osd) }, outStart); }

                } else if (config.effect === 'explode') {
                    if (inDur > 0) {
                        const inStagger = n > 1 ? Math.max(3, (inDur * 0.25) / n) : 0;
                        tl.add(parts, {
                            x: [() => utils.random(-1200, 1200), 0],
                            y: [() => utils.random(-800, 800), 0],
                            rotate: [() => utils.random(-180, 180), 0],
                            duration: () => utils.random(Math.max(150, inDur * 0.4), inDur),
                            ease: 'inOut(2)',
                            delay: stagger(inStagger, { from: 'random' }),
                        }, inStart);
                    }
                    if (outDur > 0) {
                        const outStagger = n > 1 ? Math.max(3, (outDur * 0.15) / n) : 0;
                        tl.add(parts, {
                            x: { to: () => utils.random(-1200, 1200), duration: () => utils.random(150, Math.max(200, outDur * 0.7)) },
                            y: () => utils.random(-800, 800),
                            rotate: () => utils.random(-180, 180),
                            duration: () => utils.random(200, Math.max(250, outDur * 0.9)),
                            ease: 'outCirc',
                            delay: stagger(outStagger, { from: 'random' }),
                        }, outStart);
                    }

                } else if (config.effect === 'slide-fade') {
                    if (inDur > 0) {
                        const { perDur, sd } = computeStagger(n, inDur, granularity);
                        tl.add(parts, { opacity: [0, 1], ease: inEase, duration: perDur, delay: stagger(sd) }, inStart);
                    }
                    if (outDur > 0) { const { perDur: od, sd: osd } = computeStagger(n, outDur, granularity); tl.add(parts, { opacity: [1, 0], duration: od, ease: outEase, delay: stagger(osd) }, outStart); }
                }
            }
        }

        timelineRef.current = tl;
        tl.seek(timeController.getTime() * 1000);

        return () => {
            if (timelineRef.current) timelineRef.current.pause();
            if (splitterRef.current) {
                try { splitterRef.current.revert(); } catch {}
                splitterRef.current = null;
            }
        };
    }, [config.content, config.effect, config.granularity, config.easing, config.speed, config.stackTransition, config.inDuration, config.outDuration, config.delay, config.duration, config.intensity, config.lineHeight, config.fontSize, config.fontFamily, config.fontWeight, config.letterSpacing, config.color, config.textAlign, animationKey]);

    // Time subscription
    useEffect(() => {
        const update = (time: number) => {
            const c = configRef.current;
            const timeMs = time * 1000;
            if (timelineRef.current) timelineRef.current.seek(timeMs);

            // Kinetic per-frame computation
            const kType = kineticTypeRef.current;
            if (kType && kineticPartsRef.current.length > 0) {
                const localTime = timeMs - c.delay;
                if (localTime >= 0 && localTime <= c.duration) {
                    applyKineticFrame(kType, kineticPartsRef.current, localTime, c.speed, c.intensity, kineticLineIndicesRef.current);
                }
            }

            if (containerRef.current) {
                const isVisible = timeMs >= c.delay && timeMs <= (c.delay + c.duration);
                containerRef.current.style.opacity = isVisible ? '1' : '0';
                containerRef.current.style.pointerEvents = (isVisible && !c.locked) ? 'auto' : 'none';
            }
        };
        update(timeController.getTime());
        const unsubscribe = timeController.subscribe(update);
        return unsubscribe;
    }, [config.delay, config.duration]);

    return (
        <div
            ref={containerRef}
            onMouseDown={(e) => onSelectLayer(e, config.id)}
            className="absolute cursor-move active:cursor-grabbing"
            style={{
                left: `${config.position.x}%`,
                top: `${config.position.y}%`,
                transform: `translate(-${config.position.x}%, -${config.position.y}%)${config.rotation ? ` rotate(${config.rotation}deg)` : ''}`,
                width: 'max-content',
                opacity: 0,
                pointerEvents: 'none',
                overflow: 'visible',
                padding: '20px',
            }}
        >
            <div ref={rootRef} style={{ ...styles, overflow: 'visible' }} />
            {selectedId === config.id && <BoundingBox
                onResizeStart={() => { resizeStartFontSize.current = config.fontSize; }}
                onResize={(_corner, dx) => {
                    const newSize = Math.max(8, Math.round(resizeStartFontSize.current + dx / 2));
                    onUpdateLayer?.(config.id, { fontSize: newSize });
                }}
                onResizeEnd={() => onResizeEnd?.()}
            />}
        </div>
    );
};

export const AnimatedText = memo(AnimatedTextComponent);

import React, { useCallback } from 'react';

interface BoundingBoxProps {
  color?: string;
  /** When provided, corner handles become interactive for resizing */
  onResizeStart?: (corner: string) => void;
  onResize?: (corner: string, dx: number, dy: number) => void;
  onResizeEnd?: () => void;
}

type Corner = 'tl' | 'tr' | 'bl' | 'br';

const CURSORS: Record<Corner, string> = {
  tl: 'nwse-resize',
  tr: 'nesw-resize',
  bl: 'nesw-resize',
  br: 'nwse-resize',
};

export const BoundingBox: React.FC<BoundingBoxProps> = ({
  color = '#4dff00',
  onResizeStart,
  onResize,
  onResizeEnd,
}) => {
  const handleSize = 14;
  const half = handleSize / 2;
  const isInteractive = !!onResize;

  const handleMouseDown = useCallback((e: React.MouseEvent, corner: Corner) => {
    if (!onResize) return;
    e.stopPropagation();
    e.preventDefault();
    onResizeStart?.(corner);

    const startX = e.clientX;
    const startY = e.clientY;

    // Corner-aware direction: dragging "outward" from center always means grow
    const signX = corner.endsWith('l') ? -1 : 1;
    const signY = corner.startsWith('t') ? -1 : 1;

    const onMove = (ev: MouseEvent) => {
      const rawDx = ev.clientX - startX;
      const rawDy = ev.clientY - startY;
      // Combine into a single diagonal delta — uniform grow/shrink feel
      const effectiveDelta = (signX * rawDx + signY * rawDy) / 2;
      onResize(corner, effectiveDelta, effectiveDelta);
    };

    const onUp = () => {
      onResizeEnd?.();
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  }, [onResize, onResizeStart, onResizeEnd]);

  const cornerStyle = (corner: Corner): React.CSSProperties => ({
    position: 'absolute',
    width: handleSize,
    height: handleSize,
    backgroundColor: color,
    pointerEvents: isInteractive ? 'auto' : 'none',
    cursor: isInteractive ? CURSORS[corner] : 'default',
    zIndex: 10000,
    ...(corner.startsWith('t') ? { top: -half } : { bottom: -half }),
    ...(corner.endsWith('l') ? { left: -half } : { right: -half }),
  });

  return (
    <div className="absolute inset-0 pointer-events-none" style={{ zIndex: 9999 }}>
      {/* Border */}
      <div className="absolute inset-0 border" style={{ borderColor: color }} />
      {/* Corner handles */}
      <div style={cornerStyle('tl')} onMouseDown={(e) => handleMouseDown(e, 'tl')} />
      <div style={cornerStyle('tr')} onMouseDown={(e) => handleMouseDown(e, 'tr')} />
      <div style={cornerStyle('bl')} onMouseDown={(e) => handleMouseDown(e, 'bl')} />
      <div style={cornerStyle('br')} onMouseDown={(e) => handleMouseDown(e, 'br')} />
    </div>
  );
};

