// ── Click Outside ──
function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { document.removeEventListener('mousedown', listener); document.removeEventListener('touchstart', listener); };
  }, [ref, handler]);
}

// ── Field Dropdown (Figma-matched) ──
export const FieldDropdown: React.FC<{
  label?: string; value: string; options: { value: string; label: string }[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [flipUp, setFlipUp] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  const selectedLabel = options.find(o => o.value === String(value))?.label || value;

  const handleToggle = () => {
    if (!isOpen && ref.current) {
      const rect = ref.current.getBoundingClientRect();
      const spaceBelow = window.innerHeight - rect.bottom;
      setFlipUp(spaceBelow < 280);
    }
    setIsOpen(!isOpen);
  };

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={handleToggle}
        className="w-full text-left border-[0.5px] border-black hover:border-[#666] transition-colors rounded-[8px] flex items-center justify-between px-[6px] py-[4px] select-none focus:outline-none bg-white">
        <div className="flex flex-col items-start w-full">
          {label && <p className="text-[8px] text-[#6d6d6d] tracking-[-0.48px]">{label}</p>}
          <p className="text-[16px] text-black tracking-[-0.96px]">{selectedLabel}</p>
        </div>
        <Icon name="keyboard_arrow_down" size={16} className={`text-[#6d6d6d] transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>
      {isOpen && (
        <div
          className={`absolute z-50 left-0 w-full bg-white border-[0.5px] border-black rounded-[8px] overflow-hidden shadow-xl animate-dropdown ${flipUp ? 'origin-bottom' : 'origin-top'}`}
          style={flipUp ? { bottom: 'calc(100% + 4px)' } : { top: 'calc(100% + 4px)' }}
        >
          <div className="max-h-[260px] overflow-y-auto light-scrollbar">
            {options.map((opt) => (
              <button key={opt.value} type="button"
                className={`w-full text-left px-2.5 py-2 text-[14px] tracking-[-0.56px] hover:bg-[#f5f5f5] transition-colors ${String(value) === opt.value ? 'bg-[#ececec] text-black' : 'text-[rgba(0,0,0,0.7)]'}`}
                onClick={() => { onChange(opt.value); setIsOpen(false); }}>
                {opt.label}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

