// ── Text Input ──
export const TextInput: React.FC<{
  value: string; onChange: (val: string) => void; placeholder?: string; autoResize?: boolean; onFocus?: () => void; className?: string;
}> = ({ value, onChange, placeholder, autoResize, onFocus, className = '' }) => {
  const ref = useRef<HTMLTextAreaElement>(null);

  const resize = () => {
    if (autoResize && ref.current) {
      ref.current.style.height = 'auto';
      ref.current.style.height = ref.current.scrollHeight + 'px';
    }
  };

  useLayoutEffect(() => {
    resize();
  }, [value, autoResize]);

  useEffect(() => {
    let raf1: number, raf2: number;
    raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => resize());
    });
    return () => { cancelAnimationFrame(raf1); cancelAnimationFrame(raf2); };
  }, [value, autoResize]);

  return (
    <textarea ref={ref} value={value} onFocus={onFocus} onChange={(e) => {
      onChange(e.target.value);
    }}
      placeholder={placeholder}
      rows={1}
      className={`w-full px-[5px] py-[5px] resize-none overflow-y-auto light-scrollbar bg-white text-[14px] leading-snug text-black tracking-[-0.02em] focus:outline-none transition-colors ${className}`} />
  );
};

