// ── Mask Preview Canvas — renders the actual masked subject ──
const MaskPreviewCanvas: React.FC<{ layer: MediaLayer }> = ({ layer }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const cached = getPreviewCache(layer.id);
        if (!cached) return;

        const { framePixels, mask, width, height } = cached;
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d')!;

        const processed = processMask(mask, width, height, {
            threshold: layer.threshold ?? 0.5,
            invert: layer.invert ?? false,
            choke: layer.choke ?? 0,
            feather: layer.feather ?? 0,
        });

        const composited = new ImageData(
            new Uint8ClampedArray(framePixels.data),
            width, height
        );
        const px = composited.data;
        for (let i = 0; i < processed.length; i++) {
            px[i * 4 + 3] = Math.round(processed[i] * 255);
        }
        ctx.clearRect(0, 0, width, height);
        ctx.putImageData(composited, 0, 0);
    }, [layer.id, layer.threshold, layer.invert, layer.choke, layer.feather]);

    return (
        <canvas
            ref={canvasRef}
            className="w-full h-full object-contain"
        />
    );
};

// ── Content Preview with bounding-box handles ──
const ContentPreview: React.FC<{
    layer: Layer;
    layers: Layer[];
    onUpdateLayer: (id: string, updates: Partial<Layer>) => void;
}> = ({ layer, layers, onUpdateLayer }) => {
    const handleSize = 7.685;
    const half = handleSize / 2;

    const CornerHandles: React.FC<{ color?: string }> = ({ color = 'black' }) => (
        <>
            <div style={{ position: 'absolute', top: -half, left: -half, width: handleSize, height: handleSize, backgroundColor: color }} />
            <div style={{ position: 'absolute', top: -half, right: -half, width: handleSize, height: handleSize, backgroundColor: color }} />
            <div style={{ position: 'absolute', bottom: -half, left: -half, width: handleSize, height: handleSize, backgroundColor: color }} />
            <div style={{ position: 'absolute', bottom: -half, right: -half, width: handleSize, height: handleSize, backgroundColor: color }} />
        </>
    );

    if (isTextLayer(layer)) {
        return (
            <div className="relative bg-[#ececec] rounded-[10px] px-2 py-2 flex flex-col gap-2 h-[132px]">
                <div className="accent-bar" />
                <SectionLabel>Content</SectionLabel>
                <div className="relative">
                    <div className="border border-black h-[82px] overflow-hidden">
                        <TextInput
                            value={layer.content}
                            className="h-full"
                            placeholder="Enter text..."
                            onChange={val => onUpdateLayer(layer.id, { content: val })}
                        />
                    </div>
                    <CornerHandles />
                </div>
            </div>
        );
    }

    if (isMediaLayer(layer)) {
        const isVideo = layer.type === 'video';
        const mediaSrc = isVideo && layer.mediaAsset.dataUrl ? `${layer.mediaAsset.dataUrl}#t=0.001` : layer.mediaAsset.dataUrl;
        return (
            <div className="relative bg-[#ececec] rounded-[10px] px-2 py-2 flex flex-col gap-2 h-[132px]">
                <div className="accent-bar" />
                <SectionLabel>{isVideo ? 'Video' : 'Image'}</SectionLabel>
                <div className="relative">
                    <div className="border border-black h-[82px] overflow-hidden bg-black/5">
                        {/* Raw media — always mounted */}
                        {layer.mediaAsset.dataUrl && (
                            isVideo ? (
                                <video src={mediaSrc} className="w-full h-full object-cover" preload="metadata" muted playsInline />
                            ) : (
                                <img src={mediaSrc} className="w-full h-full object-cover" alt="" />
                            )
                        )}
                        {/* Mask overlay — fades in on top when active */}
                        {layer.hasMask && (
                            <>
                                <div className="absolute inset-0 bg-black">
                                    <MaskPreviewCanvas layer={layer} />
                                </div>
                                <div className="absolute bottom-1 left-1 px-1.5 py-0.5 bg-black/60 rounded text-[8px] text-[#00ff88] font-medium tracking-wide">
                                    MASK
                                </div>
                            </>
                        )}
                    </div>
                    <CornerHandles />
                </div>
            </div>
        );
    }

    return null;
};

export const Sidebar: React.FC<SidebarProps> = ({
    selectedLayer, layers, projectConfig, onUpdateProjectConfig, onUpdateLayer,
    onAddMedia, onExport, onExtractSubject,
    isRendering, renderProgress, hasLayers, isExtracting, extractionProgress
}) => {
    const [activeTab, setActiveTab] = useState<'design' | 'animate'>('design');

    const updateSelected = (updates: Partial<any>) => {
        if (selectedLayer) onUpdateLayer(selectedLayer.id, updates);
    };

    // ── Common Layer Properties ──
    const renderCommonControls = (layer: Layer) => (
        <>
            <div className="flex flex-col gap-[4px] items-start w-full">
                <RangeSlider
                    label="OPACITY"
                    value={layer.opacity}
                    min={0} max={100}
                    formatValue={v => `${Math.round(v)}%`}
                    onChange={v => updateSelected({ opacity: v })}
                />
            </div>
            <div className="flex flex-col gap-[8px] items-start w-full">
                <SectionLabel>Blend Mode</SectionLabel>
                <FieldDropdown
                    value={layer.blendMode}
                    options={BLEND_MODES.map(b => ({ value: b.value, label: b.label }))}
                    onChange={v => updateSelected({ blendMode: v as BlendMode })}
                    className="w-full"
                />
            </div>
        </>
    );

    // ── Reusable Position Grid ──
    // When elementSize is provided (media/solid), positions are edge-aware:
    // left/top edges align to canvas edges, right/bottom edges align to opposite edges.
    const renderPositionGrid = (layer: { position: { x: number; y: number } }, elementSize?: { w: number; h: number }) => {
        const computePos = (preset: { x: number; y: number }) => {
            if (!elementSize) return { x: preset.x, y: preset.y };
            const hw = elementSize.w / 2;
            const hh = elementSize.h / 2;
            // Map preset edges: 10 → edge-flush, 50 → center, 90 → opposite-edge-flush
            const mapX = preset.x <= 10 ? Math.max(0, hw)
                : preset.x >= 90 ? Math.min(100, 100 - hw)
                    : 50;
            const mapY = preset.y <= 10 ? Math.max(0, hh)
                : preset.y >= 90 ? Math.min(100, 100 - hh)
                    : 50;
            return { x: Math.round(mapX * 10) / 10, y: Math.round(mapY * 10) / 10 };
        };

        return (
            <div className="flex flex-col gap-[8px] items-start w-full">
                <SectionLabel>Position</SectionLabel>
                <div className="w-full max-w-[256px] h-[110px] rounded-[10px] border-[0.5px] border-black overflow-hidden grid grid-cols-3 grid-rows-3 bg-white">
                    {POSITION_PRESETS.map((p, idx) => {
                        const target = computePos(p);
                        const isSelected = Math.abs(layer.position.x - target.x) < 0.5 && Math.abs(layer.position.y - target.y) < 0.5;
                        const borderRight = (idx % 3 !== 2) ? 'border-r border-[rgba(0,0,0,0.1)]' : '';
                        const borderBottom = (Math.floor(idx / 3) !== 2) ? 'border-b border-[rgba(0,0,0,0.1)]' : '';
                        return (
                            <button key={p.name} onClick={() => updateSelected({ position: target })}
                                className={`flex justify-center items-center ${borderRight} ${borderBottom} transition-all duration-150 active:scale-95\n                                    ${isSelected ? 'bg-[#4a4a4a] text-white' : 'text-[rgba(0,0,0,0.3)] hover:text-[rgba(0,0,0,0.7)] hover:bg-black/5'}`}
                                title={p.name}>
                                <Icon name={POSITION_ICONS[p.icon] || 'center_focus_strong'} size={16} />
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    };

    // ── Text Layer — Design Tab ──
    const renderTextDesignControls = (layer: TextLayer) => {
        const selectedFont = FONTS.find(f => f.family === layer.fontFamily);
        const availableWeights = selectedFont?.weights || [400];

        return (
            <>
                {/* Card 1: Typography */}
                <div className="card">
                    {/* Typography */}
                    <div className="flex flex-col gap-[8px] items-start w-full">
                        <SectionLabel>Typography</SectionLabel>
                        <div className="flex flex-col gap-[12px] items-start w-full">
                            <div className="flex gap-[4px] w-full">
                                <FieldDropdown
                                    label="Font"
                                    value={layer.fontFamily}
                                    options={FONTS.map(f => ({ value: f.family, label: f.name }))}
                                    onChange={(v) => {
                                        const newFont = FONTS.find(f => f.family === v);
                                        const updates: Partial<TextLayer> = { fontFamily: v };
                                        if (newFont && !newFont.weights.includes(layer.fontWeight)) {
                                            updates.fontWeight = newFont.weights.includes(400) ? 400 : newFont.weights[0];
                                        }
                                        updateSelected(updates);
                                    }}
                                    className="flex-1"
                                />
                                <FieldDropdown
                                    label="Weight"
                                    value={String(layer.fontWeight)}
                                    options={availableWeights.map(w => ({ value: String(w), label: WEIGHT_LABELS[w] }))}
