                                    className="flex-1"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Sliders */}
                    <div className="flex flex-col gap-[12px] items-start w-full">
                        <RangeSlider label="Size" value={layer.fontSize} min={12} max={300} onChange={v => updateSelected({ fontSize: v })} formatValue={v => `${Math.round(v)}`} />
