                        <ColorBar color={layer.color} onChange={v => updateSelected({ color: v })} />
                        <RangeSlider label="Opacity" value={layer.opacity} min={0} max={100} formatValue={v => `${Math.round(v)}%`} onChange={v => updateSelected({ opacity: v })} />
                    </div>

                    {/* Blend Mode */}
                    <div className="flex flex-col gap-[8px] items-start w-full">
                        <SectionLabel>Blend Mode</SectionLabel>
                        <FieldDropdown
                            value={layer.blendMode}
                            options={BLEND_MODES.map(b => ({ value: b.value, label: b.label }))}
                            onChange={v => updateSelected({ blendMode: v as BlendMode })}
                            className="w-full"
                        />
                    </div>
                </div>

                {/* Card 2: Position */}
                <div className="card">
                    {renderPositionGrid(layer)}
