                                formatValue={v => `${(v * 100).toFixed(0)}%`}
                                onChange={v => updateSelected({ threshold: v })} />
                            <RangeSlider label="Choke" value={layer.choke ?? 0} min={0} max={10} step={0.5}
                                formatValue={v => `${v}px`} onChange={v => updateSelected({ choke: v })} />
                            <RangeSlider label="Feather" value={layer.feather ?? 0} min={0} max={20} step={0.5}
                                formatValue={v => `${v}px`} onChange={v => updateSelected({ feather: v })} />

