                                {activeTab === id && (
                                    id === 'design' ? (
                                        <div className="absolute top-0 left-full bottom-0 w-[4px] bg-gradient-to-r from-[rgba(0,0,0,0.15)] to-transparent pointer-events-none" />
                                    ) : (
                                        <div className="absolute top-0 right-full bottom-0 w-[4px] bg-gradient-to-l from-[rgba(0,0,0,0.15)] to-transparent pointer-events-none" />
                                    )
                                )}
                            </button>
                        ))}
                    </div>

                    {/* Scrollable cards area */}
                    <div className="flex-1 min-h-0 overflow-y-auto light-scrollbar flex flex-col items-center w-full px-2 pb-2 pt-2 gap-2 bg-[#ececec] rounded-b-[10px] rounded-tr-[10px]">
                        {renderTextControls(selectedLayer)}
                    </div>
                </div>
            ) : selectedLayer ? (
                <div className="flex flex-col w-[280px] mx-[auto] mt-2 mb-2 min-h-0 flex-1">
                    <div className="flex-1 min-h-0 overflow-y-auto light-scrollbar flex flex-col items-center w-full px-2 pb-2 pt-2 gap-2 bg-[#ececec] rounded-[10px]">
                        {isMediaLayer(selectedLayer)
                            ? renderMediaControls(selectedLayer)
                            : isSolidColorLayer(selectedLayer)
                                ? renderSolidControls(selectedLayer)
                                : null}
                    </div>
                </div>
            ) : null}
        </div>
    );
};

import React, { useRef, useEffect, useState, useCallback, useMemo } from 'react';
import { Layer, TextLayer, MediaLayer, SolidColorLayer, ProjectConfig,
         isTextLayer, isMediaLayer, isSolidColorLayer } from '../types';
import { AnimatedText } from './AnimatedText';
import { BoundingBox } from './BoundingBox';
import { timeController } from '../services/TimeController';
import { getPreviewCache, processMask } from '../services/rotoscope';

// ── Mask Canvas ─────────────────────────────────────────────────
// Renders source pixels + mask alpha from the preview cache.
// Overlays on top of the raw media when hasMask is true.

const MaskCanvas: React.FC<{ layer: MediaLayer; className?: string; style?: React.CSSProperties }> = ({ layer, className, style }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas || !layer.hasMask) return;
        const cached = getPreviewCache(layer.id);
        if (!cached) return;

        const { framePixels, mask, width, height } = cached;
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d')!;

        const processed = processMask(mask, width, height, {
            threshold: layer.threshold ?? 0.5,
            invert: layer.invert ?? false,
            choke: layer.choke ?? 0,
            feather: layer.feather ?? 0,
        });

        const composited = new ImageData(
            new Uint8ClampedArray(framePixels.data),
            width, height
        );
        const px = composited.data;
        for (let i = 0; i < processed.length; i++) {
            px[i * 4 + 3] = Math.round(processed[i] * 255);
        }
        ctx.putImageData(composited, 0, 0);
    }, [layer.id, layer.hasMask, layer.threshold, layer.invert, layer.choke, layer.feather]);

    if (!layer.hasMask) return null;

    return (
        <canvas
            ref={canvasRef}
            className={className}
            style={style}
        />
    );
};


// ── Stage Props ─────────────────────────────────────────────────

interface StageProps {
    layers: Layer[];
    projectConfig: ProjectConfig;
    selectedLayerId: string | null;
    isPlaying: boolean;
    animationKey: number;
    duration: number;
    onUpdateLayerPosition: (id: string, pos: { x: number; y: number }) => void;
    onUpdateLayer?: (id: string, updates: Partial<Layer>) => void;
    onDragEnd?: () => void;
    onVideoMetadataLoaded: (layerId: string, duration: number) => void;
    onSelectLayer: (id: string) => void;
    placeholderDuration?: number;
}

export const Stage: React.FC<StageProps> = ({
    layers,
    projectConfig,
    selectedLayerId,
    isPlaying,
    animationKey,
    duration,
    onUpdateLayerPosition,
    onUpdateLayer,
    onDragEnd,
    onVideoMetadataLoaded,
    onSelectLayer,
    placeholderDuration = 8
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const parentRef = useRef<HTMLDivElement>(null);
    const videoRefs = useRef<Map<string, HTMLVideoElement>>(new Map());
    const [dragRenderTick, setDragRenderTick] = useState(0);
    const isDraggingRef = useRef(false);
    const draggingLayerIdRef = useRef<string | null>(null);
    const dragPosRef = useRef<{ x: number; y: number } | null>(null);
    const dragStartPos = useRef<{ x: number; y: number } | null>(null);
    const dragMouseStart = useRef<{ x: number; y: number } | null>(null);
    const onUpdateLayerPositionRef = useRef(onUpdateLayerPosition);
    const onUpdateLayerRef = useRef(onUpdateLayer);
    const onDragEndRef = useRef(onDragEnd);
    onUpdateLayerPositionRef.current = onUpdateLayerPosition;
    onUpdateLayerRef.current = onUpdateLayer;
    onDragEndRef.current = onDragEnd;
    // Track starting value for resize operations
    const resizeStartRef = useRef<number>(0);
    const [stageScale, setStageScale] = useState<number>(1);
    const rafId = useRef<number>();
    const lastTime = useRef<number>(performance.now());

    // ── Time-gated visibility for non-text layers ──────────────────
    // Subscribes to timeController and toggles display on elements
    // with data-time-delay / data-time-duration attributes.
    // Text layers handle this internally via AnimatedText.
    const stageOverlaysRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        const update = (time: number) => {
            const container = stageOverlaysRef.current;
            if (!container) return;
            const timeMs = time * 1000;
            container.querySelectorAll<HTMLElement>('[data-time-delay]').forEach(el => {
                const delay = parseFloat(el.dataset.timeDelay || '0');
                const dur = parseFloat(el.dataset.timeDuration || 'Infinity');
                const visible = timeMs >= delay && timeMs <= delay + dur;
                el.style.display = visible ? '' : 'none';
            });
        };
        update(timeController.getTime());
        return timeController.subscribe(update);
    }, []);

    // Measure parent and compute a uniform scale factor so the stage
    // always renders at the full canvas resolution (canvasWidth × canvasHeight)
    // and is scaled down to fit the viewport.  This keeps every px-based
    // value (font sizes, letter spacing, positions) stable across resizes.
    const canvasW = projectConfig.canvasWidth;
    const canvasH = projectConfig.canvasHeight;

    useEffect(() => {
        const parent = parentRef.current;
        if (!parent) return;

        const computeScale = () => {
            const pw = parent.clientWidth;
            const ph = parent.clientHeight;
            if (pw === 0 || ph === 0) return;

            // Scale so the full canvas fits inside the parent (object-fit: contain)
            const scale = Math.min(pw / canvasW, ph / canvasH);
            setStageScale(scale);
        };

        const ro = new ResizeObserver(computeScale);
        ro.observe(parent);
        computeScale();

        return () => ro.disconnect();
    }, [canvasW, canvasH]);

    // Sorted by zIndex for rendering (lowest first = background)
    const sortedLayers = [...layers].sort((a, b) => a.zIndex - b.zIndex);


    // Find primary video for time source
    const primaryVideoLayer = layers.find(l => l.type === 'video' && l.visible) as MediaLayer | undefined;

    const updateLoop = useCallback(() => {
        if (isPlaying) {
            const now = performance.now();
            const delta = (now - lastTime.current) / 1000;
            lastTime.current = now;

            const primaryVideo = primaryVideoLayer ? videoRefs.current.get(primaryVideoLayer.id) : null;
            if (primaryVideo) {
                timeController.setTime(primaryVideo.currentTime);
            } else {
                const effectiveDuration = duration || placeholderDuration;
                const nextTime = (timeController.getTime() + delta) % effectiveDuration;
                timeController.setTime(nextTime);
            }
            rafId.current = requestAnimationFrame(updateLoop);
        }
    }, [isPlaying, placeholderDuration, duration, primaryVideoLayer]);

    useEffect(() => {
        lastTime.current = performance.now();
        if (isPlaying) {
            rafId.current = requestAnimationFrame(updateLoop);
        } else {
            if (rafId.current) cancelAnimationFrame(rafId.current);
        }
        return () => { if (rafId.current) cancelAnimationFrame(rafId.current); };
    }, [isPlaying, updateLoop]);

    // Play/pause all visible video layers
    useEffect(() => {
        videoRefs.current.forEach(video => {
            if (isPlaying) video.play().catch(() => {});
            else video.pause();
        });
    }, [isPlaying]);

    // Scrub sync
    useEffect(() => {
        const unsubscribe = timeController.subscribe((time) => {
            if (isPlaying) return;
            videoRefs.current.forEach(video => {
                video.currentTime = time;
            });
        });
        return unsubscribe;
    }, [isPlaying]);

    // Layer dragging — uses pixel deltas so direction is never inverted
    const handleMouseDown = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        e.preventDefault(); // Prevent native browser drag on images
        onSelectLayer(id);
        const layer = layers.find(l => l.id === id);
        if (layer?.locked) return;

        let targetId = id;

        const targetLayer = layers.find(l => l.id === targetId);

        // Store the starting mouse position for delta-based dragging
        dragMouseStart.current = { x: e.clientX, y: e.clientY };

        isDraggingRef.current = true;
        draggingLayerIdRef.current = targetId;
        if (targetLayer && 'position' in targetLayer) {
            dragPosRef.current = { ...targetLayer.position };
            dragStartPos.current = { ...targetLayer.position };
        }
        setDragRenderTick(t => t + 1); // trigger initial render with drag state
    };

    // Stable window-level mousemove/mouseup — refs avoid effect re-attachment
    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!isDraggingRef.current || !containerRef.current || !draggingLayerIdRef.current || !dragStartPos.current || !dragMouseStart.current) return;
            const rect = containerRef.current.getBoundingClientRect();
            // Compute mouse delta in container-percent space
            const deltaX = ((e.clientX - dragMouseStart.current.x) / rect.width) * 100;
            const deltaY = ((e.clientY - dragMouseStart.current.y) / rect.height) * 100;
            dragPosRef.current = {
                x: Math.max(0, Math.min(100, dragStartPos.current.x + deltaX)),
                y: Math.max(0, Math.min(100, dragStartPos.current.y + deltaY))
            };
            setDragRenderTick(t => t + 1); // trigger re-render with new position
        };
        const handleMouseUp = () => {
            if (!isDraggingRef.current) return;
            const layerId = draggingLayerIdRef.current;
            const pos = dragPosRef.current;
            const startPos = dragStartPos.current;
            const didMove = layerId && pos && startPos &&
                (Math.abs(pos.x - startPos.x) > 0.01 ||
                 Math.abs(pos.y - startPos.y) > 0.01);
            if (didMove) {
                onUpdateLayerPositionRef.current(layerId, pos);
            }
            isDraggingRef.current = false;
            draggingLayerIdRef.current = null;
            dragPosRef.current = null;
            dragStartPos.current = null;
            dragMouseStart.current = null;
            setDragRenderTick(t => t + 1); // clear drag visual state
            if (didMove) {
                onDragEndRef.current?.();
            }
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, []); // stable — never re-attaches

    const setVideoRef = useCallback((id: string) => (el: HTMLVideoElement | null) => {
        if (el) videoRefs.current.set(id, el);
        else videoRefs.current.delete(id);
    }, []);

    const handleVideoMetadata = (layerId: string) => (e: React.SyntheticEvent<HTMLVideoElement>) => {
        const video = e.currentTarget;
        onVideoMetadataLoaded(layerId, video.duration);
    };

    // Compute bgOpacity from text layers
    const bgOpacity = layers.reduce((max, l) => {
        if (isTextLayer(l)) return Math.max(max, l.bgOpacity || 0);
        return max;
    }, 0);

    // Display dimensions for the outer wrapper (layout-affecting)
    const displayW = Math.round(canvasW * stageScale);
    const displayH = Math.round(canvasH * stageScale);

    return (
        <div ref={parentRef} className="w-full h-full flex items-center justify-center">
        {/* Outer wrapper: takes up display-sized layout space for flex centering + drag handling */}
        <div
            ref={containerRef}
            id="stage-container"
            className="relative shadow-2xl group select-none border border-white/5 rounded-xl"
            style={{
                width: displayW,
                height: displayH,
                overflow: 'hidden',
            }}
        >
            {/* Inner div: native canvas resolution, scaled down to fit */}
            <div
                style={{
                    width: canvasW,
                    height: canvasH,
                    transform: `scale(${stageScale})`,
                    transformOrigin: 'top left',
                    position: 'relative',
                    backgroundColor: projectConfig.backgroundColor,
                    backgroundImage: projectConfig.backgroundColor === 'transparent' || projectConfig.backgroundColor === '#000000'
                        ? 'none'
                        : undefined,
                }}
            >
            {/* Checkerboard pattern for canvas */}
            <div
                className="absolute inset-0 pointer-events-none"
                style={{
                    backgroundImage: `\n                        linear-gradient(45deg, #1a1a1a 25%, transparent 25%),\n                        linear-gradient(-45deg, #1a1a1a 25%, transparent 25%),\n                        linear-gradient(45deg, transparent 75%, #1a1a1a 75%),\n                        linear-gradient(-45deg, transparent 75%, #1a1a1a 75%)\n                    `,
                    backgroundSize: '16px 16px',
                    backgroundPosition: '0 0, 0 8px, 8px -8px, -8px 0px',
                    opacity: 0.3,
                    zIndex: 0,
                }}
            />

            {/* Layer Compositing — background is inside so blend modes composite against it */}
            <div id="stage-overlays" ref={stageOverlaysRef} className="absolute inset-0 z-10 pointer-events-none" style={{ isolation: 'isolate' }}>
                {/* Canvas background color/gradient — participates in blend mode mixing */}
                <div
                    className="absolute inset-0 pointer-events-none"
                    style={{
                        backgroundColor: !projectConfig.backgroundGradient ? projectConfig.backgroundColor : undefined,
                        backgroundImage: projectConfig.backgroundGradient || undefined,
                        zIndex: 0,
                    }}
                />

                {/* Dim Overlay (from text bg opacity) */}
                <div
                    className="absolute inset-0 bg-black pointer-events-none"
                    style={{ opacity: bgOpacity / 100, zIndex: 1 }}
                />


                {sortedLayers.map(baseLayer => {
                    if (!baseLayer.visible) return null;

                    // Fast local drag update
                    const isDragged = baseLayer.id === draggingLayerIdRef.current && dragPosRef.current;
                    const layer = (isDragged && 'position' in baseLayer) 
                        ? { ...baseLayer, position: dragPosRef.current } as typeof baseLayer
                        : baseLayer;

                    // ─── Solid Color Layer ───
                    if (isSolidColorLayer(layer)) {
                        return (
                            <div
                                key={layer.id}
                                data-time-delay={layer.delay}
                                data-time-duration={layer.duration}
                                className="absolute cursor-move"
                                style={{
                                    left: `${layer.position.x}%`,
                                    top: `${layer.position.y}%`,
                                    width: `${layer.size.width}%`,
                                    height: `${layer.size.height}%`,
                                    transform: `translate(-50%, -50%)`,
                                    backgroundColor: layer.fillColor,
                                    opacity: layer.opacity / 100,
                                    mixBlendMode: layer.blendMode,
                                    zIndex: layer.zIndex + 2,
                                    pointerEvents: layer.locked ? 'none' : 'auto',
                                }}
                                onMouseDown={(e) => handleMouseDown(e, layer.id)}
                            >
                                {selectedLayerId === layer.id && <BoundingBox
                                    onResizeStart={() => { resizeStartRef.current = layer.size.width; }}
                                    onResize={(_corner, dx, _dy) => {
                                        if (!containerRef.current) return;
                                        const rect = containerRef.current.getBoundingClientRect();
                                        const deltaPct = (dx / rect.width) * 100;
                                        const newW = Math.max(5, resizeStartRef.current + deltaPct);
                                        const ar = layer.size.width / layer.size.height;
                                        onUpdateLayerRef.current?.(layer.id, { size: { width: newW, height: newW / ar } });
                                    }}
                                    onResizeEnd={() => onDragEndRef.current?.()}
                                />}
                            </div>
                        );
                    }

                    // ─── Media Layer (Video/Image) ───
                    if (isMediaLayer(layer)) {
                        const nw = layer.mediaAsset.naturalWidth || 1920;
                        const nh = layer.mediaAsset.naturalHeight || 1080;
                        const mediaAR = nw / nh;
                        const canvasAR = projectConfig.canvasWidth / projectConfig.canvasHeight;
                        const widthPct = layer.scale;
                        const heightPct = (widthPct / mediaAR) * canvasAR;

                        const wrapperStyle: React.CSSProperties = {
                            left: `${layer.position.x}%`,
                            top: `${layer.position.y}%`,
                            width: `${widthPct}%`,
                            height: `${heightPct}%`,
                            transform: `translate(-50%, -50%)`,
                            zIndex: layer.zIndex + 2,
                            pointerEvents: layer.locked ? 'none' : 'auto',
                        };
                        const innerStyle: React.CSSProperties = {
                            objectFit: 'fill' as const,
                            opacity: layer.opacity / 100,
                            mixBlendMode: layer.blendMode,
                        };

                        if (layer.mediaAsset.type === 'video') {
                            return (
                                <div key={layer.id} className="absolute cursor-move" style={wrapperStyle}
                                    data-time-delay={layer.delay}
                                    data-time-duration={layer.duration}
                                    onMouseDown={(e) => handleMouseDown(e, layer.id)}>
                                    {layer.hasMask ? (
                                        <MaskCanvas layer={layer} className="w-full h-full" style={innerStyle} />
                                    ) : (
                                        <video
                                            ref={setVideoRef(layer.id)}
                                            data-layer-id={layer.id}
                                            src={layer.mediaAsset.dataUrl}
                                            className="w-full h-full"
                                            style={innerStyle}
                                            muted loop playsInline
                                            onLoadedMetadata={handleVideoMetadata(layer.id)}
                                        />
                                    )}
                                    {selectedLayerId === layer.id && <BoundingBox
                                        onResizeStart={() => { resizeStartRef.current = layer.scale; }}
                                        onResize={(_corner, dx, _dy) => {
                                            if (!containerRef.current) return;
                                            const rect = containerRef.current.getBoundingClientRect();
                                            const deltaPct = (dx / rect.width) * 100;
                                            onUpdateLayerRef.current?.(layer.id, { scale: Math.max(5, resizeStartRef.current + deltaPct) });
                                        }}
                                        onResizeEnd={() => onDragEndRef.current?.()}
                                    />}
                                </div>
                            );
                        }
                        return (
                            <div key={layer.id} className="absolute cursor-move" style={wrapperStyle}
                                data-time-delay={layer.delay}
                                data-time-duration={layer.duration}
                                onMouseDown={(e) => handleMouseDown(e, layer.id)}>
                                {layer.hasMask ? (
                                    <MaskCanvas layer={layer} className="w-full h-full" style={innerStyle} />
                                ) : (
                                    <img src={layer.mediaAsset.dataUrl} className="w-full h-full" style={innerStyle}
                                         draggable={false} />
                                )}
                                {selectedLayerId === layer.id && <BoundingBox
                                    onResizeStart={() => { resizeStartRef.current = layer.scale; }}
                                    onResize={(_corner, dx, _dy) => {
                                        if (!containerRef.current) return;
                                        const rect = containerRef.current.getBoundingClientRect();
                                        const deltaPct = (dx / rect.width) * 100;
                                        onUpdateLayerRef.current?.(layer.id, { scale: Math.max(5, resizeStartRef.current + deltaPct) });
                                    }}
                                    onResizeEnd={() => onDragEndRef.current?.()}
                                />}
                            </div>
                        );
                    }

                    // ─── Text Layer ───
                    if (isTextLayer(layer)) {
                        return (
                            <div
                                key={layer.id}
                                className="absolute inset-0"
                                style={{
                                    opacity: layer.opacity / 100,
                                    mixBlendMode: layer.blendMode,
                                    zIndex: layer.zIndex + 2,
                                    pointerEvents: 'none',

                                }}
                            >
                                <AnimatedText
                                    config={layer}
                                    isPlaying={isPlaying}
                                    animationKey={animationKey}
                                    selectedId={selectedLayerId}
                                    onSelectLayer={(e, id) => handleMouseDown(e, id)}
                                    onUpdateLayer={onUpdateLayerRef.current}
                                    onResizeEnd={() => onDragEndRef.current?.()}
                                />
                            </div>
                        );
                    }

                    return null;
                })}
            </div>
        </div>
        </div>
        </div>
    );
};

import React, { useRef, useEffect, useCallback, memo, useState } from 'react';
import { timeController } from '../services/TimeController';
import { Layer, LayerType, LAYER_TYPE_META, isTextLayer } from '../types';
import { Icon } from './Icon';

interface TimelineProps {
    duration: number;
    layers: Layer[];
    selectedId: string | null;
    isPlaying: boolean;
    onPlayPause: () => void;
    onRestart: () => void;
    onSeek: (time: number) => void;
    onUpdateLayer: (id: string, updates: Partial<Layer>) => void;
    onBatchUpdate: (updates: Array<{ id: string; changes: Partial<Layer> }>) => void;
    onSelectLayer: (id: string) => void;
    onDeselectAll: () => void;
    onDeleteLayer: (id: string) => void;
    onReorderLayers: (layers: Layer[]) => void;
    onAddLayer: (type: LayerType) => void;
}

const MIN_BLOCK_MS = 300;
const LAYER_ROW_HEIGHT = 32;
const LAYER_INFO_WIDTH = 200;

interface DragState {
    mode: 'move' | 'resize-start' | 'resize-end';
    activeId: string;
    startX: number;
    startDelay: number;
    startDuration: number;
    currentDelay: number;
    currentDuration: number;
}



export const Timeline: React.FC<TimelineProps> = memo(({
    duration, layers, selectedId, isPlaying,
    onPlayPause, onRestart, onSeek, onUpdateLayer, onBatchUpdate, onSelectLayer,
    onDeselectAll, onDeleteLayer, onReorderLayers, onAddLayer
}) => {
    const trackAreaRef = useRef<HTMLDivElement>(null);
    const blockRefs = useRef<Map<string, HTMLDivElement>>(new Map());
    const dragRef = useRef<DragState | null>(null);
    const timeTextRef = useRef<HTMLSpanElement>(null);
    const playheadRef = useRef<HTMLDivElement>(null);
    const trackPlayheadRef = useRef<HTMLDivElement>(null);
    const [showAddMenu, setShowAddMenu] = useState(false);
    const [layerDrag, setLayerDrag] = useState<{ dragId: string; overId: string | null } | null>(null);
    const [editingLayerId, setEditingLayerId] = useState<string | null>(null);
    const editInputRef = useRef<HTMLInputElement>(null);

    // Sorted by zIndex descending (top = highest zIndex, like AE)
    const sortedLayers = [...layers].sort((a, b) => b.zIndex - a.zIndex);

    const durationRef = useRef(duration);
    durationRef.current = duration;
    const layersRef = useRef(layers);
    layersRef.current = layers;
    const onSeekRef = useRef(onSeek);
    onSeekRef.current = onSeek;
    const onSelectLayerRef = useRef(onSelectLayer);
    onSelectLayerRef.current = onSelectLayer;
    const onBatchUpdateRef = useRef(onBatchUpdate);
    onBatchUpdateRef.current = onBatchUpdate;

    /* ─── Playhead ─── */
    useEffect(() => {
        const unsubscribe = timeController.subscribe((time) => {
            if (timeTextRef.current) timeTextRef.current.innerText = formatTime(time);
            if (durationRef.current > 0) {
                const pct = `${(time / durationRef.current) * 100}%`;
                if (playheadRef.current) playheadRef.current.style.left = pct;
                if (trackPlayheadRef.current) trackPlayheadRef.current.style.left = pct;
            }
        });
        return unsubscribe;
    }, []);

    const getTimeFromX = useCallback((clientX: number) => {
        if (!trackAreaRef.current || durationRef.current === 0) return 0;
        const rect = trackAreaRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        return Math.max(0, Math.min(1, x / rect.width)) * durationRef.current;
    }, []);

    /* ─── Seek on track background ─── */
    const handleTrackMouseDown = useCallback((e: React.MouseEvent) => {
        if ((e.target as HTMLElement).closest('[data-block-id]')) return;
        onSeekRef.current(getTimeFromX(e.clientX));
        const onMove = (ev: MouseEvent) => onSeekRef.current(getTimeFromX(ev.clientX));
        const onUp = () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [getTimeFromX]);

    /* ─── Seek on ruler area (top bar) — Premiere-style ─── */
    const handleRulerMouseDown = useCallback((e: React.MouseEvent) => {
        onSeekRef.current(getTimeFromX(e.clientX));
        const onMove = (ev: MouseEvent) => onSeekRef.current(getTimeFromX(ev.clientX));
        const onUp = () => { window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, [getTimeFromX]);

    /* ─── Block drag ─── */
    const startDrag = useCallback((e: React.MouseEvent, id: string, mode: 'move' | 'resize-start' | 'resize-end') => {
        e.stopPropagation();
        e.preventDefault();
        onSelectLayerRef.current(id);

        const currentLayers = layersRef.current;
        const layer = currentLayers.find(l => l.id === id);
        if (!layer || !trackAreaRef.current) return;

        if (mode === 'move') {
            const inDur = isTextLayer(layer) ? layer.inDuration : 0;
            const visibleTime = (layer.delay + inDur + 100) / 1000;
            const endTime = (layer.delay + layer.duration) / 1000;
            onSeekRef.current(Math.min(visibleTime, endTime, durationRef.current));
        }

        dragRef.current = {
            mode, activeId: id, startX: e.clientX,
            startDelay: layer.delay, startDuration: layer.duration,
            currentDelay: layer.delay, currentDuration: layer.duration,
        };

        const draggedEl = blockRefs.current.get(id);
        if (draggedEl) {
            draggedEl.style.transition = 'none';
            draggedEl.style.zIndex = '25';
            draggedEl.style.opacity = '0.85';
        }

        document.body.style.cursor = mode === 'move' ? 'grabbing' : 'ew-resize';

        const onMove = (ev: MouseEvent) => {
            const drag = dragRef.current;
            if (!drag || !trackAreaRef.current) return;
            const rect = trackAreaRef.current.getBoundingClientRect();
            const deltaX = ev.clientX - drag.startX;
            const deltaTimeMs = (deltaX / rect.width) * durationRef.current * 1000;
            const totalMs = durationRef.current * 1000;

            let newDelay = drag.startDelay;
            let newDuration = drag.startDuration;

            if (drag.mode === 'move') {
                newDelay = Math.max(0, Math.min(totalMs - drag.startDuration, drag.startDelay + deltaTimeMs));
                newDuration = drag.startDuration;
            } else if (drag.mode === 'resize-start') {
                const rawDelay = drag.startDelay + deltaTimeMs;
                const maxDelay = (drag.startDelay + drag.startDuration) - MIN_BLOCK_MS;
                newDelay = Math.max(0, Math.min(maxDelay, rawDelay));
                newDuration = (drag.startDelay + drag.startDuration) - newDelay;
            } else {
                const rawEnd = (drag.startDelay + drag.startDuration) + deltaTimeMs;
                newDuration = Math.max(MIN_BLOCK_MS, Math.min(totalMs - drag.startDelay, rawEnd - drag.startDelay));
                newDelay = drag.startDelay;
            }

            const el = blockRefs.current.get(drag.activeId);
            if (el) {
                el.style.left = `${(newDelay / 1000 / durationRef.current) * 100}%`;
                el.style.width = `${(newDuration / 1000 / durationRef.current) * 100}%`;
            }
            drag.currentDelay = newDelay;
            drag.currentDuration = newDuration;
        };

        const onUp = () => {
            const drag = dragRef.current;
            if (drag) {
                // Reset visual state
                const el = blockRefs.current.get(drag.activeId);
                if (el) {
                    el.style.transition = 'opacity 150ms ease-out';
                    el.style.opacity = '';
                    el.style.zIndex = '';
                }

                // Commit the dragged block's new position
                setTimeout(() => {
                    if (el) el.style.transition = '';
                    onUpdateLayer(drag.activeId, {
                        delay: drag.currentDelay,
                        duration: drag.currentDuration,
                    });
                }, 50);
            }
            document.body.style.cursor = '';
            dragRef.current = null;
            window.removeEventListener('mousemove', onMove);
            window.removeEventListener('mouseup', onUp);
        };

        window.addEventListener('mousemove', onMove);
        window.addEventListener('mouseup', onUp);
    }, []);

    const setBlockRef = useCallback((id: string) => (el: HTMLDivElement | null) => {
        if (el) blockRefs.current.set(id, el);
        else blockRefs.current.delete(id);
    }, []);

    /* ─── Layer row reorder (drag) ─── */
    const handleLayerDragStart = (e: React.DragEvent, id: string) => {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', id);
        setLayerDrag({ dragId: id, overId: null });
    };
    const handleLayerDragOver = (e: React.DragEvent, id: string) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        if (layerDrag) setLayerDrag({ ...layerDrag, overId: id });
    };
    const handleLayerDrop = (e: React.DragEvent, targetId: string) => {
        e.preventDefault();
        const sourceId = e.dataTransfer.getData('text/plain');
        if (!sourceId || sourceId === targetId) { setLayerDrag(null); return; }
        const sorted = [...sortedLayers];
        const fromIdx = sorted.findIndex(l => l.id === sourceId);
        const toIdx = sorted.findIndex(l => l.id === targetId);
        if (fromIdx === -1 || toIdx === -1) { setLayerDrag(null); return; }
        const [moved] = sorted.splice(fromIdx, 1);
        sorted.splice(toIdx, 0, moved);
        // Safety: never lose layers during reorder
        if (sorted.length !== sortedLayers.length) { setLayerDrag(null); return; }
        const reindexed = sorted.map((l, i) => ({ ...l, zIndex: sorted.length - i }));
        onReorderLayers(reindexed);
        setLayerDrag(null);
    };
    const handleLayerDragEnd = () => setLayerDrag(null);

    /* ─── Layer move via arrows ─── */
    const handleMoveLayer = (id: string, direction: 'up' | 'down') => {
        const sorted = [...sortedLayers];
        const idx = sorted.findIndex(l => l.id === id);
        if (idx === -1) return;
        const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
        if (targetIdx < 0 || targetIdx >= sorted.length) return;
        const temp = sorted[idx];
        sorted[idx] = sorted[targetIdx];
        sorted[targetIdx] = temp;
        const reindexed = sorted.map((l, i) => ({ ...l, zIndex: sorted.length - i }));
        onReorderLayers(reindexed);
    };

    const addLayerOptions: { type: LayerType; label: string; icon: string }[] = [
        { type: 'text', label: 'Text', icon: 'title' },
        { type: 'image', label: 'Media', icon: 'image' },
        { type: 'solid-color', label: 'Solid', icon: 'square' },
    ];

    /* ─── Generate time ruler ticks ─── */
    const generateTicks = () => {
        if (duration === 0) return [];
        const ticks: { time: number; label: string; major: boolean }[] = [];
        // Aim for ~8-12 ticks
        const interval = duration <= 5 ? 0.5 : duration <= 15 ? 1 : duration <= 60 ? 5 : 10;
        for (let t = 0; t <= duration; t += interval) {
            // Skip first and last ticks — they get clipped at the edges
            if (t === 0 || t >= duration - interval * 0.5) continue;
            const major = t % (interval * 2) === 0 || interval >= 1;
            ticks.push({ time: t, label: formatTime(t), major });
        }
        return ticks;
    };

    if (duration === 0) return null;

    const ticks = generateTicks();

    return (
        <div className="w-full select-none flex flex-col bg-[#ececec] rounded-[10px]">
            {/* ── Transport Controls ── */}
            <div className="flex items-center gap-[8px] px-2 py-[8px]">
                <div className="relative size-[24px] shrink-0">
                    <div className="absolute inset-0 bg-[#f0f0f0] rounded-full border-[0.5px] border-black" />
                    <button onClick={onPlayPause}
                        className="relative w-full h-full flex items-center justify-center text-black cursor-pointer z-10">
                        <Icon name={isPlaying ? 'pause' : 'play_arrow'} size={16} filled />
                    </button>
                </div>
                <span ref={timeTextRef}
                    className="text-[14px] font-bold text-[#c1c1c1] tabular-nums min-w-[52px]">
                    {formatTime(timeController.getTime())}
                </span>
                <div className="flex-1" />
                <span className="text-[14px] font-bold text-[#c1c1c1] tabular-nums">
                    {formatTime(duration)}
                </span>
            </div>

            {/* ── Timeline Body: Layer Info (left) + Tracks (right) ── */}
            <div className="border-t border-white/80" />
            <div className="flex overflow-y-auto light-scrollbar shadow-[0_-2px_6px_rgba(0,0,0,0.06)]" style={{ minHeight: 170, maxHeight: '50vh' }}>
                {/* ─── Left: Layer Info Column ─── */}
                <div className="flex flex-col shrink-0 bg-white rounded-bl-[10px] rounded-tl-[10px] shadow-[4px_0px_4px_0px_rgba(0,0,0,0.1)]"
                    style={{ width: LAYER_INFO_WIDTH }}>
                    {/* Header */}
                    <div className="flex items-center justify-between px-2 h-[32px] shrink-0 border-b-[0.5px] border-black">
                        <span className="text-[10px] font-bold text-black tracking-[-0.3px]">LAYERS</span>
                        <div className="relative">
                            <div className="relative size-[24px]">
                                <div className="absolute inset-0 bg-[#ececec] rounded-full" />
                                <button onClick={() => setShowAddMenu(!showAddMenu)}
                                    className="relative w-full h-full flex items-center justify-center text-black cursor-pointer z-10">
                                    <Icon name="add" size={14} />
                                </button>
                            </div>
                            {showAddMenu && (
                                <div className="absolute right-0 top-full mt-1 z-50 bg-white border-[0.5px] border-black rounded-[8px] overflow-hidden shadow-2xl animate-dropdown min-w-[120px]">
                                    {addLayerOptions.map(opt => (
                                        <button key={opt.type}
                                            onClick={() => { onAddLayer(opt.type); setShowAddMenu(false); }}
                                            className="w-full flex items-center gap-2 px-2.5 py-2 text-[10px] font-bold text-black tracking-[-0.3px] hover:bg-[#f5f5f5] transition-colors">
                                            <Icon name={opt.icon} size={12} className="text-[#6d6d6d]" />
                                            {opt.label}
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Layer Rows */}
                    <div className="flex-1 overflow-hidden">
                        {sortedLayers.map(layer => {
                            const isSelected = selectedId === layer.id;
                            const meta = LAYER_TYPE_META[layer.type];
                            const color = meta.color;
                            const displayName = (isTextLayer(layer) && layer.name === 'Text') ? (layer.content?.split(String.fromCharCode(10)).join(' ').slice(0, 18) || 'Text') : layer.name;
                            const isDragOver = layerDrag?.overId === layer.id && layerDrag?.dragId !== layer.id;

                            return (
                                <div
                                    key={layer.id}
                                    className={`flex items-stretch border-t-[0.5px] border-black ${isDragOver ? 'bg-[#e0e0e0]' : ''}`}
                                    style={{ height: LAYER_ROW_HEIGHT - 3 }}
                                >
                                    {/* Main layer row body */}
                                    <div
                                        draggable
                                        onDragStart={(e) => handleLayerDragStart(e, layer.id)}
                                        onDragOver={(e) => handleLayerDragOver(e, layer.id)}
                                        onDrop={(e) => handleLayerDrop(e, layer.id)}
                                        onDragEnd={handleLayerDragEnd}
                                        onClick={() => onSelectLayer(layer.id)}
                                        className={`\n                                            group flex-1 flex items-center gap-[4px] px-2 py-[4px] cursor-pointer transition-colors select-none min-w-0\n                                            ${isSelected ? 'bg-[#f0f0f0]' : 'hover:bg-[#f8f8f8]'}\n                                        `}
                                    >
                                        {/* Visibility */}
                                        <button
                                            onClick={(e) => { e.stopPropagation(); onUpdateLayer(layer.id, { visible: !layer.visible }); }}
                                            className="shrink-0 flex items-center justify-center text-[#6d6d6d] hover:text-black transition-colors"
                                        >
                                            <Icon name={layer.visible ? 'visibility' : 'visibility_off'} size={16} />
                                        </button>

                                        {/* Lock */}
                                        <button
                                            onClick={(e) => { e.stopPropagation(); onUpdateLayer(layer.id, { locked: !layer.locked }); }}
                                            className={`shrink-0 flex items-center justify-center transition-colors ${layer.locked ? 'text-black' : 'text-[#6d6d6d] hover:text-black'}`}
                                        >
                                            <Icon name={layer.locked ? 'lock' : 'lock_open'} size={14} />
                                        </button>

                                        {/* Type icon */}
                                        <Icon name={meta.icon} size={16} className="shrink-0" style={{ color } as any} />

                                        {/* Name — editable on double-click */}
                                        {editingLayerId === layer.id ? (
                                            <input
                                                ref={editInputRef}
                                                defaultValue={layer.name}
                                                className="flex-1 text-[10px] text-black tracking-[-0.3px] bg-white border border-black/20 rounded px-1 py-0 outline-none min-w-0"
                                                onBlur={(e) => {
                                                    const val = e.currentTarget.value.trim();
                                                    if (val) onUpdateLayer(layer.id, { name: val });
                                                    setEditingLayerId(null);
                                                }}
                                                onKeyDown={(e) => {
                                                    if (e.key === 'Enter') { e.currentTarget.blur(); }
                                                    if (e.key === 'Escape') { setEditingLayerId(null); }
                                                    e.stopPropagation();
                                                }}
                                                onClick={(e) => e.stopPropagation()}
                                                autoFocus
                                                onFocus={(e) => e.currentTarget.select()}
                                            />
                                        ) : (
                                            <span
                                                className="flex-1 text-[10px] text-black tracking-[-0.3px] truncate"
                                                onDoubleClick={(e) => { e.stopPropagation(); setEditingLayerId(layer.id); }}
                                            >
                                                {displayName}
                                            </span>
                                        )}

                                        {/* Delete */}
                                        <button
                                            onClick={(e) => { e.stopPropagation(); onDeleteLayer(layer.id); }}
                                            className="shrink-0 w-4 h-4 flex items-center justify-center rounded opacity-0 group-hover:opacity-100 text-[rgba(0,0,0,0.2)] hover:!text-red-500/70 transition-all"
                                        >
                                            <Icon name="close" size={10} />
                                        </button>

                                        {/* Up/down arrows */}
                                        <div className="flex flex-col shrink-0 -my-1">
                                            <button
                                                onClick={(e) => { e.stopPropagation(); handleMoveLayer(layer.id, 'up'); }}
                                                disabled={sortedLayers.indexOf(layer) === 0}
                                                className="flex items-center justify-center text-[#6d6d6d] hover:text-black disabled:opacity-20 transition-all"
                                            >
                                                <Icon name="keyboard_arrow_up" size={12} />
                                            </button>
                                            <button
                                                onClick={(e) => { e.stopPropagation(); handleMoveLayer(layer.id, 'down'); }}
                                                disabled={sortedLayers.indexOf(layer) === sortedLayers.length - 1}
                                                className="flex items-center justify-center text-[#6d6d6d] hover:text-black disabled:opacity-20 transition-all"
                                            >
                                                <Icon name="keyboard_arrow_down" size={12} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}

                        {layers.length === 0 && (
                            <div className="flex items-center justify-center py-6 text-[10px] text-[rgba(0,0,0,0.15)]">
                                No layers
                            </div>
                        )}

                        {/* Canvas row — always at bottom */}
                        <div
                            onClick={onDeselectAll}
                            className={`\n                                group flex items-center gap-[4px] px-2 py-[4px] cursor-pointer transition-colors\n                                border-t-[0.5px] border-b-[0.5px] border-black\n                                ${selectedId === null ? 'bg-[#f0f0f0]' : 'hover:bg-[#f8f8f8]'}\n                            `}
                            style={{ height: LAYER_ROW_HEIGHT - 3 }}
                        >
                            <div className="w-8 shrink-0" /> {/* Spacer to align with type icon in layer rows */}
                            <Icon name="dashboard" size={16} className="shrink-0 text-[#6d6d6d]" />
                            <span className="flex-1 text-[10px] text-black tracking-[-0.3px] truncate">
                                Canvas
                            </span>
                        </div>
                    </div>
                </div>

                {/* ─── Right: Track Area ─── */}
                <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
                    {/* Time Ruler — clicking/dragging here seeks the playhead */}
                    <div className="relative border-b-[0.5px] border-black shrink-0 cursor-pointer"
                        style={{ height: 32 }}
                        onMouseDown={handleRulerMouseDown}>
                        {ticks.map(tick => (
                            <div
                                key={tick.time}
                                className="absolute top-0 bottom-0 flex flex-col items-center pointer-events-none"
                                style={{ left: `${(tick.time / duration) * 100}%` }}
                            >
                                <span className="text-[8px] font-bold text-[rgba(0,0,0,0.5)] tabular-nums whitespace-nowrap mt-[14px]"
                                    style={{ transform: 'translateX(-50%)' }}>
                                    {tick.label}
                                </span>
                            </div>
                        ))}
                        {/* Playhead indicator in ruler */}
                        <div
                            ref={playheadRef}
                            className="absolute top-0 bottom-0 z-40 pointer-events-none"
                            style={{
                                left: `${(timeController.getTime() / duration) * 100}%`,
                            }}
                        >
                            <div className="absolute top-0 left-1/2 -translate-x-1/2 w-3 h-3 bg-black rounded-sm rotate-45 -translate-y-[2px]" />
                            <div className="absolute top-0 bottom-0 left-1/2 -translate-x-1/2 w-px bg-black" />
                        </div>
                    </div>

                    {/* Track Rows */}
                    <div
                        ref={trackAreaRef}
                        className="flex-1 relative overflow-hidden"
                        onMouseDown={handleTrackMouseDown}
                    >
                        {sortedLayers.map((layer) => {
                            const startPercent = ((layer.delay || 0) / 1000 / duration) * 100;
                            const widthPercent = ((layer.duration || 0) / 1000 / duration) * 100;
                            const isSelected = selectedId === layer.id;
                            const meta = LAYER_TYPE_META[layer.type];
                            const color = meta.color;

                            const inDur = isTextLayer(layer) ? layer.inDuration : 0;
                            const outDur = isTextLayer(layer) ? layer.outDuration : 0;
                            const inW = layer.duration > 0 ? (inDur / layer.duration) * 100 : 0;
                            const outW = layer.duration > 0 ? (outDur / layer.duration) * 100 : 0;
                            const displayName = (isTextLayer(layer) && layer.name === 'Text') ? (layer.content?.split(String.fromCharCode(10)).join(' ').slice(0, 14) || 'Text') : layer.name;

                            return (
                                <div
                                    key={layer.id}
                                    className="relative border-t-[0.5px] border-black"
                                    style={{ height: LAYER_ROW_HEIGHT - 3 }}
                                >
                                    {/* Duration block */}
                                    <div
                                        ref={setBlockRef(layer.id)}
                                        data-block-id={layer.id}
                                        onMouseDown={(e) => startDrag(e, layer.id, 'move')}
                                        className={`absolute top-[2px] bottom-[2px] rounded-[8px] z-10 cursor-grab active:cursor-grabbing\n                                             overflow-hidden group/clip will-change-[left,width] transition-colors`}
                                        style={{
                                            left: `${startPercent}%`,
                                            width: `${widthPercent}%`,
                                            backgroundColor: isSelected ? color + '66' : color + '40',
                                        }}
                                    >
                                        {/* In/Out transition zone indicators */}
                                        {inW > 0 && (
                                            <div className="absolute left-0 top-0 bottom-0 pointer-events-none"
                                                style={{ width: `${inW}%` }}>
                                                <div className="absolute inset-0 rounded-l" style={{ backgroundColor: color + '30' }} />
                                                <div className="absolute right-0 top-[3px] bottom-[3px] w-px" style={{ backgroundColor: color + '60' }} />
                                            </div>
                                        )}
                                        {outW > 0 && (
                                            <div className="absolute right-0 top-0 bottom-0 pointer-events-none"
                                                style={{ width: `${outW}%` }}>
                                                <div className="absolute inset-0 rounded-r" style={{ backgroundColor: color + '30' }} />
                                                <div className="absolute left-0 top-[3px] bottom-[3px] w-px" style={{ backgroundColor: color + '60' }} />
                                            </div>
                                        )}

                                        {/* Resize handles */}
                                        <div onMouseDown={(e) => startDrag(e, layer.id, 'resize-start')}
                                            className="absolute left-0 top-0 bottom-0 w-1.5 cursor-ew-resize hover:bg-black/10 z-30 transition-colors rounded-l" />
                                        <div onMouseDown={(e) => startDrag(e, layer.id, 'resize-end')}
                                            className="absolute right-0 top-0 bottom-0 w-1.5 cursor-ew-resize hover:bg-black/10 z-30 transition-colors rounded-r" />

                                        {/* Label */}
                                        <div className="absolute inset-0 flex items-center px-2 gap-1 pointer-events-none overflow-hidden">
                                            <span
                                                className="text-[9px] font-medium tracking-[0.1px] whitespace-nowrap truncate text-black">
                                                {displayName}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}

                        {/* Canvas row spacer — matches left side */}
                        <div
                            className="border-t-[0.5px] border-b-[0.5px] border-black"
                            style={{ height: LAYER_ROW_HEIGHT - 3 }}
                        />

                        {/* Playhead line — spans all track rows */}
                        <div
                            ref={trackPlayheadRef}
                            className="absolute top-0 bottom-0 z-40 pointer-events-none"
                            style={{
                                left: `${(timeController.getTime() / duration) * 100}%`,
                            }}
                        >
                            <div className="absolute top-0 bottom-0 left-1/2 -translate-x-1/2 w-px bg-black" />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
});

function formatTime(seconds: number) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
}

