/**
 * Manually fetch Google Fonts CSS and inline the font files as base64.
 */
async function fetchGoogleFontCSS(): Promise<string> {
  const links = Array.from(document.querySelectorAll('link[rel="stylesheet"]'))
    .filter(el => (el as HTMLLinkElement).href?.includes('fonts.googleapis.com'));

  if (links.length === 0) return '';

  const cssChunks: string[] = [];

  for (const link of links) {
    try {
      const res = await fetch((link as HTMLLinkElement).href, {
        headers: { 'Accept': 'text/css' }
      });
      const css = await res.text();

      const urlRegex = new RegExp('url\\((https?:\\/\\/[^)]+)\\)', 'g');
      let inlined = css;
      const matches = [...css.matchAll(urlRegex)];

      for (const match of matches) {
        try {
          const fontRes = await fetch(match[1]);
          const fontBuf = await fontRes.arrayBuffer();
          const b64 = arrayBufferToBase64(fontBuf);
          const mime = match[1].includes('.woff2') ? 'font/woff2'
            : match[1].includes('.woff') ? 'font/woff'
            : 'font/truetype';
          inlined = inlined.replace(match[0], `url(data:${mime};base64,${b64})`);
        } catch { }
      }

      cssChunks.push(inlined);
    } catch { }
  }

  return cssChunks.join(String.fromCharCode(10));
}

/**
 * Capture a DOM element as a canvas image.
 * When useVideoOptimizations is true, applies style whitelisting,
 * preferred font format, and invisible-node filtering for speed.
 */
async function captureElement(
  el: HTMLElement,
  fontCSS: string,
  pixelRatio: number,
  useVideoOptimizations: boolean = false
): Promise<HTMLCanvasElement> {
  return toCanvas(el, {
    fontEmbedCSS: fontCSS || undefined,
    width: el.offsetWidth,
    height: el.offsetHeight,
    pixelRatio,
    skipAutoScale: true,
    ...(useVideoOptimizations && {
      includeStyleProperties: OVERLAY_STYLE_WHITELIST,
      preferredFontFormat: 'woff2' as const,
      filter: overlayNodeFilter,
    }),
  });
}

// ─── Find primary video layer ────────────────────────────────

function findVideoLayer(layers: Layer[]) {
  return layers.find(l => l.visible && isMediaLayer(l) && l.mediaAsset.type === 'video');
}

// ─── Find image background layer ─────────────────────────────

function findImageLayer(layers: Layer[]) {
  return layers.find(l => l.visible && isMediaLayer(l) && l.mediaAsset.type === 'image');
}

/**
 * Generate a silent WebM video from a still image canvas.
 * Uses captureStream(0) + requestFrame() to force frame emission.
 */
async function generateStillVideo(
  bgCanvas: HTMLCanvasElement,
  durationSec: number,
  fps: number = 24
): Promise<Blob> {
  const ctx = bgCanvas.getContext('2d')!;
  const imageData = ctx.getImageData(0, 0, bgCanvas.width, bgCanvas.height);

  const stream = bgCanvas.captureStream(0);
  const videoTrack = stream.getVideoTracks()[0] as any;

  const mediaRecorder = new MediaRecorder(stream, {
    mimeType: 'video/webm;codecs=vp9',
    videoBitsPerSecond: 8_000_000,
  });

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  return new Promise((resolve, reject) => {
    let redrawInterval: ReturnType<typeof setInterval>;

    mediaRecorder.onstop = () => {
      clearInterval(redrawInterval);
      resolve(new Blob(chunks, { type: 'video/webm' }));
    };
    mediaRecorder.onerror = reject;
    mediaRecorder.start();

    redrawInterval = setInterval(() => {
      ctx.putImageData(imageData, 0, 0);
      if (videoTrack.requestFrame) videoTrack.requestFrame();
    }, 1000 / fps);

    setTimeout(() => {
      mediaRecorder.stop();
      stream.getTracks().forEach(t => t.stop());
    }, durationSec * 1000);
  });
}

// ── Shared background renderer ──────────────────────────────

function applyBackground(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  config: ProjectConfig
) {
  const grad = config.backgroundGradient;
  if (grad) {
    const match = grad.startsWith('linear-gradient(') && grad.endsWith(')');
    if (match) {
      const inner = grad.slice('linear-gradient('.length, -1);
      const firstComma = inner.indexOf(',');
      const anglePart = firstComma !== -1 ? inner.slice(0, firstComma).trim() : inner.trim();
      const colorStops = firstComma !== -1 ? inner.slice(firstComma + 1).split(',').map(s => s.trim()) : [];
      let angle = 0;
      const degIdx = anglePart.indexOf('deg');
      if (degIdx !== -1) angle = parseFloat(anglePart.slice(0, degIdx)) * Math.PI / 180;

      const cx = w / 2, cy = h / 2;
      const len = Math.max(w, h);
      const x0 = cx - Math.cos(angle) * len;
      const y0 = cy - Math.sin(angle) * len;
      const x1 = cx + Math.cos(angle) * len;
      const y1 = cy + Math.sin(angle) * len;

      const canvasGrad = ctx.createLinearGradient(x0, y0, x1, y1);
      colorStops.forEach((color, i) => {
        canvasGrad.addColorStop(i / (colorStops.length - 1), color);
      });
      ctx.fillStyle = canvasGrad;
    } else {
      ctx.fillStyle = config.backgroundColor;
    }
  } else {
    ctx.fillStyle = config.backgroundColor;
  }
  ctx.fillRect(0, 0, w, h);
}

// ─── VIDEO EXPORT ────────────────────────────────────────────

export async function renderVideoExport(
  layers: Layer[],
  projectConfig: ProjectConfig,
  onProgress: (p: number) => void,
  signal?: AbortSignal,
  totalDuration: number = 8
) {
  const videoLayer = findVideoLayer(layers);
  const hasVideoSource = videoLayer && isMediaLayer(videoLayer);

  await document.fonts.ready;

  const overlayEl = getStageElement();
  if (!overlayEl) throw new Error("Stage overlay element not found");

  const fontCSS = await fetchGoogleFontCSS();

  // ── Output dimensions from the project canvas preset ──
  const outW = projectConfig.canvasWidth;
  const outH = projectConfig.canvasHeight;

  let sourceBlob: Blob;
  let media: MediaLayer | null = null;
  let widthFrac = 0, heightFrac = 0, posX = 0.5, posY = 0.5;

  if (hasVideoSource) {
    // Video source — use directly
    media = videoLayer as MediaLayer;
    const nw = media.mediaAsset.naturalWidth || 1920;
    const nh = media.mediaAsset.naturalHeight || 1080;
    const mediaAR = nw / nh;
    const canvasAR = outW / outH;
    widthFrac = media.scale / 100;
    heightFrac = (widthFrac / mediaAR) * canvasAR;
    posX = (media.position?.x ?? 50) / 100;
    posY = (media.position?.y ?? 50) / 100;

    const response = await fetch(media.mediaAsset.dataUrl);
    sourceBlob = await response.blob();
  } else {
    // No video — generate a still video from image background or canvas bg
    const bgCanvas = document.createElement('canvas');
    bgCanvas.width = outW;
    bgCanvas.height = outH;
    const bgCtx = bgCanvas.getContext('2d')!;

    const imageLayer = findImageLayer(layers);
    if (imageLayer && isMediaLayer(imageLayer)) {
      // Draw the image as background
      const img = new Image();
      img.src = imageLayer.mediaAsset.dataUrl;
      await img.decode();

      // Apply the background gradient/color first
      bgCtx.fillStyle = projectConfig.backgroundColor;
      bgCtx.fillRect(0, 0, outW, outH);

      // Draw the image layer at its position & scale
      const nw = imageLayer.mediaAsset.naturalWidth || img.width;
      const nh = imageLayer.mediaAsset.naturalHeight || img.height;
      const imgAR = nw / nh;
      const canvasAR = outW / outH;
      const wPct = imageLayer.scale / 100;
      const hPct = (wPct / imgAR) * canvasAR;
      const drawW = wPct * outW;
      const drawH = hPct * outH;
      const drawX = ((imageLayer.position?.x ?? 50) / 100) * outW - drawW / 2;
      const drawY = ((imageLayer.position?.y ?? 50) / 100) * outH - drawH / 2;
      bgCtx.globalAlpha = (imageLayer.opacity ?? 100) / 100;
      bgCtx.drawImage(img, drawX, drawY, drawW, drawH);
      bgCtx.globalAlpha = 1;
    } else {
      // Just background color/gradient
      bgCtx.fillStyle = projectConfig.backgroundColor;
      bgCtx.fillRect(0, 0, outW, outH);
    }

    onProgress(0.02);
    // Generate at 1fps to minimize real-time frame callbacks
    sourceBlob = await generateStillVideo(bgCanvas, totalDuration, 1);
    onProgress(0.05);
  }

  const input = new Input({ source: new BlobSource(sourceBlob), formats: ALL_FORMATS });
  const output = new Output({
    format: new Mp4OutputFormat({ fastStart: "in-memory" }),
    target: new BufferTarget()
  });

  timeController.isLocked = true;

  let renderCanvas: HTMLCanvasElement | null = null;
  let renderCtx: CanvasRenderingContext2D | null = null;
  let overlayPixelRatio = 1;

  // Parse background gradient into a CanvasGradient (linear-gradient support)
  const paintBg = (ctx: CanvasRenderingContext2D, w: number, h: number) =>
    applyBackground(ctx, w, h, projectConfig);

  try {
    const conversion = await Conversion.init({
      input,
      output,
      video: {
        forceTranscode: true,
        width: outW,
        height: outH,
        fit: 'fill',
        // Preserve source video FPS; only force 24fps for generated still videos
        ...(hasVideoSource ? {} : { frameRate: PROJECT_FPS }),
        bitrate: 8_000_000,
        keyFrameInterval: 24,
        processedWidth: outW,
        processedHeight: outH,
        process: async (sample: any) => {
          if (signal?.aborted) throw new Error("Render cancelled");

          if (!renderCanvas) {
            renderCanvas = document.createElement('canvas');
            renderCanvas.width = outW;
            renderCanvas.height = outH;
            renderCtx = renderCanvas.getContext('2d')!;

            const previewH = overlayEl.offsetHeight || 540;
            // Cap at 2 for video export — compressed video doesn't benefit
            // from 3x+ and this cuts html-to-image cost roughly in half
            overlayPixelRatio = Math.min(2, Math.max(1, Math.ceil(outH / previewH)));
          }

          const ctx = renderCtx!;

          // 1. Draw canvas background (gradient or solid)
          paintBg(ctx, outW, outH);

          // 2. Draw the video frame only when there is a video layer and it's within its timeline window
          if (hasVideoSource && media && media.visible) {
            const timeMs = sample.timestamp * 1000;
            const mediaStart = media.delay || 0;
            const mediaEnd = mediaStart + (media.duration || Infinity);
            if (timeMs >= mediaStart && timeMs <= mediaEnd) {
              const drawW = widthFrac * outW;
              const drawH = heightFrac * outH;
              const drawX = posX * outW - 0.5 * drawW;
              const drawY = posY * outH - 0.5 * drawH;

              ctx.globalAlpha = (media.opacity ?? 100) / 100;
              sample.draw(ctx, drawX, drawY, drawW, drawH);
              ctx.globalAlpha = 1;
            }
          } else if (!hasVideoSource) {
            // For generated still video, just draw the source frame as-is (it already has the background)
            sample.draw(ctx, 0, 0, outW, outH);
          }

          // 3. Seek animation system to this frame's time
          timeController.forceSetTime(sample.timestamp);

          // 4. Wait for DOM to flush
          await singleRAF();

          // 5. Capture all layers from the DOM overlay (text, masks, solids, etc.)
          try {
            const overlayCanvas = await captureElement(overlayEl, fontCSS, overlayPixelRatio, true);
            ctx.drawImage(overlayCanvas, 0, 0, outW, outH);
          } catch {
            // Fallback: html-to-image can't serialize tainted <canvas> elements (e.g. subject masks).
            // Skip canvas elements in the DOM capture, then composite them manually.
            try {
              const skipCanvas = (node: HTMLElement) => node.tagName !== 'CANVAS';
              const overlayCanvas = await toCanvas(overlayEl, {
                fontEmbedCSS: fontCSS || undefined,
                width: overlayEl.offsetWidth,
                height: overlayEl.offsetHeight,
                pixelRatio: overlayPixelRatio,
                skipAutoScale: true,
                filter: skipCanvas,
                includeStyleProperties: OVERLAY_STYLE_WHITELIST,
                preferredFontFormat: 'woff2' as const,
              });
              ctx.drawImage(overlayCanvas, 0, 0, outW, outH);
            } catch (fallbackErr) {
              console.warn('Overlay fallback capture also failed at', sample.timestamp, fallbackErr);
            }

            // Manually composite any visible <canvas> elements (subject masks)
            const canvasEls = overlayEl.querySelectorAll('canvas');
            for (const cvs of canvasEls) {
              if (cvs.width === 0 || cvs.height === 0) continue;
              const rect = cvs.getBoundingClientRect();
              const parentRect = overlayEl.getBoundingClientRect();
              const sx = outW / parentRect.width;
              const sy = outH / parentRect.height;
              const dx = (rect.left - parentRect.left) * sx;
              const dy = (rect.top - parentRect.top) * sy;
              const dw = rect.width * sx;
              const dh = rect.height * sy;
              try {
                ctx.drawImage(cvs, dx, dy, dw, dh);
              } catch {}
            }
          }

          return renderCanvas;
        }
      },
      // Gate audio to the video layer's timeline window — drop samples outside it
      ...(hasVideoSource && media ? {
        audio: {
          process: (sample: any) => {
            const timeMs = sample.timestamp * 1000;
            const mediaStart = media!.delay || 0;
            const mediaEnd = mediaStart + (media!.duration || Infinity);
            if (timeMs >= mediaStart && timeMs <= mediaEnd) return sample;
            return null; // drop audio outside the time window
          }
        }
      } : {})
    });

    if (!conversion.isValid) throw new Error("Invalid conversion");
    conversion.onProgress = onProgress;
    await conversion.execute();

    const buffer = output.target.buffer;
    const videoBlob = new Blob([buffer], { type: "video/mp4" });
    const dataUrl = URL.createObjectURL(videoBlob);

    // Try Flow SDK save (non-critical — app may not have it)
    try {
      const { Flow } = await import("flow-sdk");
      const base64 = arrayBufferToBase64(buffer);
      await Flow.save({ base64, mimeType: "video/mp4", name: `Poster_${Date.now()}.mp4` });
    } catch { }

    return { dataUrl, mimeType: "video/mp4" };
  } finally {
    timeController.isLocked = false;
  }
}

// ─── STILL IMAGE EXPORT ──────────────────────────────────────

export async function renderStillExport(
  layers: Layer[],
  projectConfig: ProjectConfig,
  seekTime?: number,
) {
  await document.fonts.ready;

  const overlayEl = getStageElement();
  if (!overlayEl) throw new Error("Stage overlay element not found");

  const fontCSS = await fetchGoogleFontCSS();

  // Use canvas preset dimensions for output
  const outW = projectConfig.canvasWidth;
  const outH = projectConfig.canvasHeight;

  // Create output canvas at full resolution
  const canvas = document.createElement("canvas");
  canvas.width = outW;
  canvas.height = outH;
  const ctx = canvas.getContext("2d")!;

  // 1. Draw canvas background (gradient or solid)
  applyBackground(ctx, outW, outH, projectConfig);

  // 2. Seek to the requested time
  const wasLocked = timeController.isLocked;
  timeController.isLocked = true;
  const targetTime = seekTime ?? timeController.getTime();
  timeController.forceSetTime(targetTime);
  await doubleRAF();

  try {
    // Capture stage-overlays at native canvas resolution.
    // stage-overlays contains the background gradient + all layers inside an
    // isolation context, so mix-blend-mode compositing is preserved correctly.
    // We temporarily remove the parent's scale transform and size the overlays
    // to native canvas dimensions so html-to-image captures at full res.
    const stageContainer = getStageContainer();
    const stageInner = stageContainer?.children[0] as HTMLElement | undefined;

    if (stageInner && overlayEl) {
      // Save original styles
      const savedTransform = stageInner.style.transform;
      const savedTransition = stageInner.style.transition;
      const savedContainerOverflow = stageContainer!.style.overflow;
      const savedContainerW = stageContainer!.style.width;
      const savedContainerH = stageContainer!.style.height;

      // Expand container and remove scale so inner div + overlays render at native res
      stageContainer!.style.overflow = 'hidden';
      stageContainer!.style.width = `${outW}px`;
      stageContainer!.style.height = `${outH}px`;
      stageInner.style.transition = 'none';
      stageInner.style.transform = 'none';
      await doubleRAF();

      // Capture the overlays div (includes background + all composited layers)
      const fullCapture = await captureElement(overlayEl, fontCSS, 1);
      ctx.drawImage(fullCapture, 0, 0, outW, outH);

      // Restore
      stageInner.style.transform = savedTransform;
      stageInner.style.transition = savedTransition;
      stageContainer!.style.overflow = savedContainerOverflow;
      stageContainer!.style.width = savedContainerW;
      stageContainer!.style.height = savedContainerH;
    } else {
      // Fallback
      const previewH = overlayEl.offsetHeight || 540;
      const pixelRatio = Math.max(1, Math.ceil(outH / previewH));
      const overlayCanvas = await captureElement(overlayEl, fontCSS, pixelRatio);
      ctx.drawImage(overlayCanvas, 0, 0, outW, outH);
    }
  } catch (captureErr) {
    console.warn('Still export capture failed', captureErr);
  } finally {
    if (!wasLocked) timeController.isLocked = false;
  }

  // Restore the timeline position
  timeController.forceSetTime(targetTime);

  const dataUrl = canvas.toDataURL("image/png");

  // Auto-save via Flow SDK
  try {
    const { Flow } = await import("flow-sdk");
    const base64 = dataUrl.split(',')[1];
    await Flow.save({ base64, mimeType: "image/png", name: `Poster_${Date.now()}.png` });
  } catch { }

  return { dataUrl, mimeType: "image/png" };
}

/**
 * Auto-rotoscoping service using MODNet (via Transformers.js / ONNX Runtime).
 * Produces true alpha mattes — far superior edge quality vs binary segmentation.
 *
 * Single-frame extraction + raw mask for real-time adjustments.
 */

import { AutoModel, AutoProcessor, RawImage, env } from '@huggingface/transformers';

// Disable browser Cache API — not available in Flow sandbox (about:srcdoc without allow-same-origin)
env.useBrowserCache = false;
env.allowLocalModels = false;

export interface ExtractionProgress {
    phase: 'loading-model' | 'extracting' | 'done';
    progress: number;    // 0-1
    frameIndex?: number;
    totalFrames?: number;
}

export interface MaskOptions {
    threshold?: number;  // 0-1, confidence cutoff (default: 0.5)
    invert?: boolean;    // if true, keep background instead of subject
    choke?: number;      // erode mask edges inward, in pixels (applied after threshold)
    feather?: number;    // soften mask edges, in pixels (applied after choke)
}

// ── Singleton model instances ───────────────────────────────────

const MODEL_ID = 'Xenova/modnet';

let _model: Awaited<ReturnType<typeof AutoModel.from_pretrained>> | null = null;
let _processor: Awaited<ReturnType<typeof AutoProcessor.from_pretrained>> | null = null;
let _initPromise: Promise<void> | null = null;

/**
 * Load or retrieve the MODNet model & processor singletons.
 * Prefers WebGPU, falls back to WASM.
 */
async function ensureModel(
    onProgress?: (p: ExtractionProgress) => void
): Promise<void> {
    if (_model && _processor) return;

    if (_initPromise) {
        await _initPromise;
        return;
    }

    onProgress?.({ phase: 'loading-model', progress: 0 });

    _initPromise = (async () => {
        // Detect best available device
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const device = (typeof navigator !== 'undefined' && (navigator as any).gpu) ? 'webgpu' : 'wasm';

        onProgress?.({ phase: 'loading-model', progress: 0.3 });

        _model = await AutoModel.from_pretrained(MODEL_ID, {
            dtype: 'fp32',
            device,
        });

        onProgress?.({ phase: 'loading-model', progress: 0.7 });

        _processor = await AutoProcessor.from_pretrained(MODEL_ID);

        onProgress?.({ phase: 'loading-model', progress: 1 });
    })();

    await _initPromise;
}

// ── Preview Mask Cache ──────────────────────────────────────────
// Stores the raw mask + unmasked frame pixels so the Stage can
// re-composite in real time as the user adjusts threshold/invert.

export interface CachedPreview {
    framePixels: ImageData;      // original unmasked frame pixels
    mask: Float32Array;          // raw confidence values 0-1
    width: number;
    height: number;
}

const _previewCache = new Map<string, CachedPreview>();

export function setPreviewCache(layerId: string, data: CachedPreview) {
    _previewCache.set(layerId, data);
}

export function getPreviewCache(layerId: string): CachedPreview | null {
    return _previewCache.get(layerId) || null;
}

export function clearPreviewCache(layerId: string) {
    _previewCache.delete(layerId);
}

// ── Model Inference ─────────────────────────────────────────────

/**
 * Run MODNet on a canvas to produce a Float32Array alpha matte.
 * The canvas must already have the frame drawn on it.
 */
async function inferMask(
    canvas: HTMLCanvasElement,
    width: number,
    height: number
): Promise<Float32Array> {
    if (!_model || !_processor) throw new Error('Model not loaded');

    // Convert canvas → RawImage for the processor
    const ctx = canvas.getContext('2d')!;
    const imgData = ctx.getImageData(0, 0, width, height);
    const rawImage = new RawImage(imgData.data, width, height, 4);

    // Pre-process (resize to model input resolution)
    const { pixel_values } = await _processor(rawImage);

    // Run inference — output is a single Tensor with shape [1, 1, H, W]
    const result = await _model({ input: pixel_values });
    const matteTensor = result.output;
    const rawData = matteTensor.data as Float32Array;
    const dims = matteTensor.dims as number[];

    // dims is [1, 1, H, W] — extract model output resolution
    const matteH = dims[dims.length - 2];
    const matteW = dims[dims.length - 1];

    if (matteW === width && matteH === height) {
        return new Float32Array(rawData);
    }

    // Resize via canvas (model output is smaller than source)
    const tmpCanvas = document.createElement('canvas');
    tmpCanvas.width = matteW;
    tmpCanvas.height = matteH;
    const tmpCtx = tmpCanvas.getContext('2d')!;
    const tmpImg = tmpCtx.createImageData(matteW, matteH);

    for (let i = 0; i < rawData.length; i++) {
        const v = Math.round(rawData[i] * 255);
        tmpImg.data[i * 4] = v;
        tmpImg.data[i * 4 + 1] = v;
        tmpImg.data[i * 4 + 2] = v;
        tmpImg.data[i * 4 + 3] = 255;
    }
    tmpCtx.putImageData(tmpImg, 0, 0);

    // Resize to original dimensions
    const resizeCanvas = document.createElement('canvas');
    resizeCanvas.width = width;
    resizeCanvas.height = height;
    const resizeCtx = resizeCanvas.getContext('2d')!;
    resizeCtx.drawImage(tmpCanvas, 0, 0, width, height);

    const resized = resizeCtx.getImageData(0, 0, width, height);
    const resultMask = new Float32Array(width * height);
    for (let i = 0; i < resultMask.length; i++) {
        resultMask[i] = resized.data[i * 4] / 255; // Read back from red channel
    }

    return resultMask;
}



// ── Mask Processing Pipeline ────────────────────────────────────
// Applies: invert → binary threshold → choke (erode) → feather (soften edges)
// All operations happen on the Float32Array mask, NOT as CSS filters.

/**
 * Fast separable box blur using running sums. O(1) per pixel regardless of radius.
 */
function boxBlur(data: Float32Array, width: number, height: number, radius: number): Float32Array {
    if (radius <= 0) return data;

    const len = data.length;
    const temp = new Float32Array(len);
    const result = new Float32Array(len);
    const kernelSize = radius * 2 + 1;

    // Horizontal pass
    for (let y = 0; y < height; y++) {
        const row = y * width;
        let sum = 0;

        for (let x = -radius; x <= radius; x++) {
            sum += data[row + Math.max(0, Math.min(width - 1, x))];
        }
        temp[row] = sum / kernelSize;

        for (let x = 1; x < width; x++) {
            sum += data[row + Math.min(width - 1, x + radius)]
                 - data[row + Math.max(0, x - radius - 1)];
            temp[row + x] = sum / kernelSize;
        }
    }

    // Vertical pass
    for (let x = 0; x < width; x++) {
        let sum = 0;

        for (let y = -radius; y <= radius; y++) {
            sum += temp[Math.max(0, Math.min(height - 1, y)) * width + x];
        }
        result[x] = sum / kernelSize;

        for (let y = 1; y < height; y++) {
            sum += temp[Math.min(height - 1, y + radius) * width + x]
                 - temp[Math.max(0, y - radius - 1) * width + x];
            result[y * width + x] = sum / kernelSize;
        }
    }

    return result;
}

/**
 * Process a raw confidence mask through the full pipeline:
 *  1. Invert (if requested)
 *  2. Binary threshold — below = 0, above = 1 (fully opaque)
 *  3. Choke — erode the mask edges inward (blur + re-threshold)
 *  4. Feather — blur the final mask to soften edges
 *
 * Returns a new Float32Array of alpha values in 0-1 range.
 */
export function processMask(
    rawMask: Float32Array,
    width: number,
    height: number,
    options: MaskOptions = {}
): Float32Array {
    const {
        threshold = 0.5,
        invert = false,
        choke = 0,
        feather = 0,
    } = options;

    const len = width * height;
    // eslint-disable-next-line prefer-const
    let mask: Float32Array = new Float32Array(len) as Float32Array;

    // Step 1: Invert
    for (let i = 0; i < len; i++) {
        mask[i] = invert ? 1 - rawMask[i] : rawMask[i];
    }

    // Step 2: Binary threshold
    for (let i = 0; i < len; i++) {
        mask[i] = mask[i] < threshold ? 0 : 1;
    }

    // Step 3: Choke — erode mask edges inward
    // Blur the binary mask then re-threshold at 0.5 to shrink it.
    if (choke > 0) {
        mask = boxBlur(mask, width, height, Math.round(choke)) as Float32Array;
        for (let i = 0; i < len; i++) {
            mask[i] = mask[i] >= 0.5 ? 1 : 0;
        }
    }

    // Step 4: Feather — soften the final edges
    if (feather > 0) {
        mask = boxBlur(mask, width, height, Math.round(feather)) as Float32Array;
    }

    return mask;
}



// ── Frame capture utilities ─────────────────────────────────────

function loadImage(src: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error('Failed to load image'));
        img.src = src;
    });
}

/**
 * Draw a video or image element onto a temporary canvas and return the canvas.
 */
function drawToCanvas(
    source: HTMLVideoElement | HTMLImageElement,
    width: number,
    height: number
): { canvas: HTMLCanvasElement; framePixels: ImageData } {
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d')!;
    ctx.drawImage(source, 0, 0, width, height);
    const framePixels = ctx.getImageData(0, 0, width, height);
    return { canvas, framePixels };
}

// ── Video seek utility ──────────────────────────────────────────

function seekVideo(videoSrc: string, timestamp: number): Promise<HTMLVideoElement> {
    return new Promise((resolve, reject) => {
        const video = document.createElement('video');
        video.crossOrigin = 'anonymous';
        video.muted = true;
        video.preload = 'auto';

        video.onloadedmetadata = () => {
            video.currentTime = Math.min(timestamp, video.duration);
        };

        video.onseeked = () => resolve(video);
        video.onerror = () => reject(new Error('Failed to load video'));
        video.src = videoSrc;
    });
}

// ── Public API ──────────────────────────────────────────────────

/**
 * Extract a mask from a single video frame (freeze-frame).
 * Caches the raw Float32Array mask for real-time threshold/choke/feather.
 */
export async function extractMaskPreview(
    videoSrc: string,
    timestamp: number,
    layerId: string,
    onProgress?: (p: ExtractionProgress) => void
): Promise<void> {
    await ensureModel(onProgress);
    onProgress?.({ phase: 'extracting', progress: 0 });

    const video = await seekVideo(videoSrc, timestamp);
    onProgress?.({ phase: 'extracting', progress: 0.3 });

    const width = video.videoWidth;
    const height = video.videoHeight;

    const { canvas, framePixels } = drawToCanvas(video, width, height);

    onProgress?.({ phase: 'extracting', progress: 0.5 });

    const mask = await inferMask(canvas, width, height);

    setPreviewCache(layerId, { framePixels, mask, width, height });

    video.remove();
    onProgress?.({ phase: 'done', progress: 1 });
}

/**
 * Extract a mask from a still image.
 */
export async function extractMaskFromImage(
    imageSrc: string,
    layerId: string,
    onProgress?: (p: ExtractionProgress) => void
): Promise<void> {
    await ensureModel(onProgress);
    onProgress?.({ phase: 'extracting', progress: 0 });

    const img = await loadImage(imageSrc);
    onProgress?.({ phase: 'extracting', progress: 0.3 });

    const width = img.naturalWidth;
    const height = img.naturalHeight;

    const { canvas, framePixels } = drawToCanvas(img, width, height);

    onProgress?.({ phase: 'extracting', progress: 0.5 });

    const mask = await inferMask(canvas, width, height);

    setPreviewCache(layerId, { framePixels, mask, width, height });

    onProgress?.({ phase: 'done', progress: 1 });
}

type Listener = (time: number) => void;

class TimeController {
    private time: number = 0;
    private listeners: Set<Listener> = new Set();
    public isLocked: boolean = false;

    setTime(t: number) {
        if (this.isLocked) return;
        this.time = t;
        this.notify();
    }

    forceSetTime(t: number) {
        this.time = t;
        this.notify();
    }

    getTime() {
        return this.time;
    }

    subscribe(listener: Listener) {
        this.listeners.add(listener);
        return () => {
            this.listeners.delete(listener);
        };
    }

    private notify() {
        this.listeners.forEach(l => l(this.time));
    }
}

export const timeController = new TimeController();

