// ─── Layer Types ─────────────────────────────────────────────

export type LayerType = 'text' | 'video' | 'image' | 'solid-color';

/** Base layer properties shared by all layer types */
export interface LayerBase {
    id: string;
    name: string;
    type: LayerType;
    visible: boolean;
    locked: boolean;
    opacity: number;         // 0–100
    blendMode: BlendMode;
    zIndex: number;          // rendering order, higher = on top
    // Timeline
    delay: number;           // Start time on timeline (ms)
    duration: number;        // Total lifespan on timeline (ms)
}

/** Text layer — carries all typography + animation config */
export interface TextLayer extends LayerBase {
    type: 'text';
    content: string;
    fontFamily: string;
    fontSize: number;
    fontWeight: number;
    letterSpacing: number;
    lineHeight: number;
    textAlign: 'left' | 'center' | 'right';
    color: string;
    backgroundColor: string;
    bgOpacity: number;
    position: { x: number; y: number };
    rotation: number;            // degrees, 0-360
    effect: AnimationEffect;
    granularity: AnimationGranularity;
    easing: AnimationEasing;
    speed: number;
    stackTransition: StackTransition;
    inDuration: number;
    outDuration: number;
    intensity: number;
}

/** Video or image media layer */
export interface MediaLayer extends LayerBase {
    type: 'video' | 'image';
    mediaAsset: MediaAsset;
    scale: number;                          // percentage, 100 = fill canvas width or height
    position: { x: number; y: number };     // percentage 0-100
    // ── Subject mask (optional — applied in-place via Extract Subject) ──
    hasMask?: boolean;
    threshold?: number;                     // confidence threshold 0-1
    invert?: boolean;                       // if true, keep background instead of subject
    choke?: number;                         // shrink mask edges inward 0-10px
    feather?: number;                       // soften mask edges 0-20px
}

/** Solid color fill layer */
export interface SolidColorLayer extends LayerBase {
    type: 'solid-color';
    fillColor: string;
    position: { x: number; y: number };
    size: { width: number; height: number };
}

/** Union of all layer types */
export type Layer = TextLayer | MediaLayer | SolidColorLayer;

// ─── Type Guards ─────────────────────────────────────────────

export function isTextLayer(layer: Layer | null): layer is TextLayer { return !!layer && layer.type === 'text'; }
export function isMediaLayer(layer: Layer | null): layer is MediaLayer { return !!layer && (layer.type === 'video' || layer.type === 'image'); }
export function isSolidColorLayer(layer: Layer | null): layer is SolidColorLayer { return !!layer && layer.type === 'solid-color'; }

/** Layers that have a position property */
export type PositionableLayer = TextLayer | MediaLayer | SolidColorLayer;
export function hasPosition(layer: Layer): layer is PositionableLayer { return 'position' in layer; }

