import { useRef, useCallback } from 'react';

/**
 * A generic undo / redo history stack.
 *
 * Instead of wrapping setState, this hook keeps a parallel stack of
 * deep-cloned snapshots.  The consumer calls `push(state)` after every
 * meaningful mutation and `undo()` / `redo()` to move through the stack.
 *
 * The stack caps at `maxSize` entries (default 100) to bound memory.
 */

export interface HistoryControls<T> {
    /** Push a new snapshot onto the stack.  Automatically truncates any "redo" future. */
    push: (state: T) => void;
    /** Move one step back.  Returns the previous snapshot, or `null` if at the beginning. */
    undo: () => T | null;
    /** Move one step forward.  Returns the next snapshot, or `null` if at the end. */
    redo: () => T | null;
    /** Whether an undo step is available. */
    canUndo: () => boolean;
    /** Whether a redo step is available. */
    canRedo: () => boolean;
    /** Reset the whole history to a single initial state. */
    reset: (state: T) => void;
}

function deepClone<T>(value: T): T {
    // structuredClone handles Date, Map, Set, ArrayBuffer etc. natively.
    return structuredClone(value);
}

export function useHistory<T>(maxSize = 100): HistoryControls<T> {
    // We use refs so the callbacks never cause re-renders on their own —
    // the consumer controls renders via its own setState.
    const stack = useRef<T[]>([]);
    const pointer = useRef(-1);

    const push = useCallback((state: T) => {
        // Truncate any future beyond current pointer
        stack.current = stack.current.slice(0, pointer.current + 1);
        stack.current.push(deepClone(state));

        // Enforce max size
        if (stack.current.length > maxSize) {
            stack.current = stack.current.slice(stack.current.length - maxSize);
        }

        pointer.current = stack.current.length - 1;
    }, [maxSize]);

    const undo = useCallback((): T | null => {
        if (pointer.current <= 0) return null;
        pointer.current -= 1;
        return deepClone(stack.current[pointer.current]);
    }, []);

    const redo = useCallback((): T | null => {
        if (pointer.current >= stack.current.length - 1) return null;
        pointer.current += 1;
        return deepClone(stack.current[pointer.current]);
    }, []);

    const canUndo = useCallback(() => pointer.current > 0, []);
    const canRedo = useCallback(() => pointer.current < stack.current.length - 1, []);

    const reset = useCallback((state: T) => {
        stack.current = [deepClone(state)];
        pointer.current = 0;
    }, []);

    return { push, undo, redo, canUndo, canRedo, reset };
}

import { useEffect, useRef } from 'react';
import { Layer, hasPosition } from '../types';
import { genId } from './layers';

interface KeyboardShortcutDeps {
    layersRef: React.MutableRefObject<Layer[]>;
    selectedLayerIdRef: React.MutableRefObject<string | null>;
    projectConfigRef: React.MutableRefObject<any>;
    clipboardRef: React.MutableRefObject<Layer | null>;
    setLayers: (layers: Layer[]) => void;
    setSelectedLayerId: (id: string | null) => void;
    setIsPlaying: React.Dispatch<React.SetStateAction<boolean>>;
    getNextZIndex: () => number;
    pushHistory: (layers: Layer[], config: any, selectedId: string | null) => void;
    handleDeleteLayer: (id: string) => void;
    handleUpdateLayer: (id: string, updates: Partial<Layer>) => void;
    handleUndo: () => void;
    handleRedo: () => void;
}

/**
 * Centralizes all keyboard shortcut handling.
 * Uses refs for state to avoid stale closures.
 */
export function useKeyboardShortcuts({
    layersRef,
    selectedLayerIdRef,
    projectConfigRef,
    clipboardRef,
    setLayers,
    setSelectedLayerId,
    setIsPlaying,
    getNextZIndex,
    pushHistory,
    handleDeleteLayer,
    handleUpdateLayer,
    handleUndo,
    handleRedo,
}: KeyboardShortcutDeps) {
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const active = document.activeElement;
            const isInput = active && (
                active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' ||
                (active instanceof HTMLElement && active.isContentEditable)
            );
            if (isInput) return;

            // Undo: Cmd+Z / Ctrl+Z
            if ((e.metaKey || e.ctrlKey) && e.key === 'z' && !e.shiftKey) {
                e.preventDefault();
                handleUndo();
                return;
            }
            // Redo: Cmd+Shift+Z / Ctrl+Shift+Z  OR  Cmd+Y / Ctrl+Y
            if (((e.metaKey || e.ctrlKey) && e.shiftKey && e.key === 'z') ||
                ((e.metaKey || e.ctrlKey) && e.key === 'y')) {
                e.preventDefault();
                handleRedo();
                return;
            }

            if (e.key === ' ' || e.code === 'Space') {
                e.preventDefault();
                setIsPlaying(prev => !prev);
            } else if (e.key === 'Backspace' || e.key === 'Delete') {
                if (selectedLayerIdRef.current) {
                    e.preventDefault();
                    handleDeleteLayer(selectedLayerIdRef.current);
                }
            }

            // Cmd+D: Duplicate selected layer
            if ((e.metaKey || e.ctrlKey) && e.key === 'd') {
                e.preventDefault();
                const sid = selectedLayerIdRef.current;
                if (sid) {
                    const source = layersRef.current.find(l => l.id === sid);
                    if (source) {
                        const clone = { ...JSON.parse(JSON.stringify(source)), id: genId(), zIndex: getNextZIndex() } as Layer;
                        if (hasPosition(clone)) {
                            clone.position = {
                                x: Math.min(100, clone.position.x + 2),
                                y: Math.min(100, clone.position.y + 2),
                            };
                        }
                        const next = [...layersRef.current, clone];
                        setLayers(next);
                        setSelectedLayerId(clone.id);
                        pushHistory(next, projectConfigRef.current, clone.id);
                    }
                }
                return;
            }

            // Cmd+C: Copy selected layer
            if ((e.metaKey || e.ctrlKey) && e.key === 'c') {
                e.preventDefault();
                const source = layersRef.current.find(l => l.id === selectedLayerIdRef.current);
                if (source) clipboardRef.current = JSON.parse(JSON.stringify(source));
                return;
            }

            // Cmd+V: Paste from clipboard
            if ((e.metaKey || e.ctrlKey) && e.key === 'v') {
                e.preventDefault();
                if (clipboardRef.current) {
                    const pasted = { ...JSON.parse(JSON.stringify(clipboardRef.current)), id: genId(), zIndex: getNextZIndex() } as Layer;
                    if (hasPosition(pasted)) {
                        pasted.position = {
                            x: Math.min(100, pasted.position.x + 2),
                            y: Math.min(100, pasted.position.y + 2),
                        };
                    }
                    const next = [...layersRef.current, pasted];
                    setLayers(next);
                    setSelectedLayerId(pasted.id);
                    pushHistory(next, projectConfigRef.current, pasted.id);
                }
                return;
            }

            // Arrow keys: Fine position adjustment
            if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
                const sid = selectedLayerIdRef.current;
                if (!sid) return;
                const layer = layersRef.current.find(l => l.id === sid);
                if (!layer || !hasPosition(layer)) return;
                e.preventDefault();
                const step = e.shiftKey ? 0.1 : 1;
                const pos = { ...layer.position };
                if (e.key === 'ArrowUp') pos.y = Math.max(0, pos.y - step);
                if (e.key === 'ArrowDown') pos.y = Math.min(100, pos.y + step);
                if (e.key === 'ArrowLeft') pos.x = Math.max(0, pos.x - step);
                if (e.key === 'ArrowRight') pos.x = Math.min(100, pos.x + step);
                handleUpdateLayer(sid, { position: pos });
                return;
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [handleDeleteLayer, handleUndo, handleRedo, getNextZIndex, pushHistory, handleUpdateLayer]);
}
